-- REFERENCIA SOLO PARA PRUEBAS LOCALES. Sin registros ni cuentas reales.

CREATE SCHEMA private;

SET check_function_bodies=off;

CREATE TABLE public."clients" (
 "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "gym_id" uuid NOT NULL,
 "document" text NOT NULL,
 "full_name" text,
 "phone" text DEFAULT ''::text,
 "email" text DEFAULT ''::text,
 "birth_date" date,
 "address" text DEFAULT ''::text,
 "emergency_contact" text DEFAULT ''::text,
 "medical_notes" text DEFAULT ''::text,
 "active" boolean DEFAULT true NOT NULL,
 "created_at" timestamp with time zone DEFAULT now() NOT NULL,
 "first_name" text DEFAULT ''::text NOT NULL,
 "last_name" text DEFAULT ''::text NOT NULL,
 "birthdate" date,
 "photo_path" text DEFAULT ''::text NOT NULL,
 "created_by" uuid,
 "whatsapp_opt_in" boolean DEFAULT false NOT NULL,
 "whatsapp_opt_in_at" timestamp with time zone,
 "whatsapp_opt_in_by" uuid,
 "biometric_identifier" text
);

CREATE TABLE public."plans" (
 "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "gym_id" uuid NOT NULL,
 "name" text NOT NULL,
 "duration_days" integer NOT NULL,
 "price" bigint DEFAULT 0 NOT NULL,
 "entry_limit" integer,
 "active" boolean DEFAULT true NOT NULL,
 "created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."checkins" (
 "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "gym_id" uuid NOT NULL,
 "client_id" bigint NOT NULL,
 "membership_id" bigint,
 "checkin_at" timestamp with time zone DEFAULT now() NOT NULL,
 "method" text DEFAULT 'SIMULACIÓN'::text NOT NULL,
 "result" text NOT NULL,
 "notes" text DEFAULT ''::text,
 "recorded_by" uuid
);

CREATE TABLE public."routines" (
 "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "gym_id" uuid NOT NULL,
 "client_id" bigint NOT NULL,
 "trainer_id" bigint,
 "name" text NOT NULL,
 "objective" text DEFAULT ''::text,
 "notes" text DEFAULT ''::text,
 "created_at" timestamp with time zone DEFAULT now() NOT NULL,
 "goal" text DEFAULT ''::text NOT NULL,
 "start_date" date DEFAULT CURRENT_DATE NOT NULL,
 "active" boolean DEFAULT true NOT NULL
);

CREATE TABLE public."exercises" (
 "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "gym_id" uuid NOT NULL,
 "routine_id" bigint NOT NULL,
 "name" text NOT NULL,
 "sets" text DEFAULT 1 NOT NULL,
 "repetitions" text DEFAULT ''::text,
 "weight" text DEFAULT ''::text,
 "notes" text DEFAULT ''::text,
 "sort_order" integer DEFAULT 0 NOT NULL,
 "day_name" text DEFAULT ''::text NOT NULL,
 "reps" text DEFAULT ''::text NOT NULL,
 "position" integer DEFAULT 0 NOT NULL
);

CREATE TABLE public."staff_invites" (
 "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "gym_id" uuid NOT NULL,
 "code" uuid DEFAULT gen_random_uuid() NOT NULL,
 "role" text DEFAULT 'receptionist'::text NOT NULL,
 "created_by" uuid NOT NULL,
 "created_at" timestamp with time zone DEFAULT now() NOT NULL,
 "expires_at" timestamp with time zone DEFAULT (now() + '6 mons'::interval) NOT NULL,
 "used_by" uuid,
 "used_at" timestamp with time zone
);

CREATE TABLE public."gym_events" (
 "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "gym_id" uuid NOT NULL,
 "event_type" text NOT NULL,
 "created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."trainers" (
 "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "gym_id" uuid NOT NULL,
 "full_name" text,
 "phone" text DEFAULT ''::text,
 "specialty" text DEFAULT ''::text,
 "active" boolean DEFAULT true NOT NULL,
 "created_at" timestamp with time zone DEFAULT now() NOT NULL,
 "name" text DEFAULT ''::text NOT NULL,
 "email" text DEFAULT ''::text NOT NULL,
 "hourly_rate" bigint DEFAULT 0 NOT NULL,
 "hire_date" date,
 "notes" text DEFAULT ''::text NOT NULL,
 "created_by" uuid
);

CREATE TABLE public."staff_shifts" (
 "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "gym_id" uuid NOT NULL,
 "trainer_id" bigint NOT NULL,
 "check_in_at" timestamp with time zone DEFAULT now() NOT NULL,
 "check_out_at" timestamp with time zone,
 "hourly_rate_snapshot" bigint DEFAULT 0 NOT NULL,
 "notes" text DEFAULT ''::text NOT NULL,
 "recorded_by" uuid,
 "created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."store_products" (
 "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "gym_id" uuid NOT NULL,
 "name" text NOT NULL,
 "sku" text DEFAULT ''::text NOT NULL,
 "sale_price" bigint NOT NULL,
 "stock_quantity" integer DEFAULT 0 NOT NULL,
 "low_stock_threshold" integer DEFAULT 5 NOT NULL,
 "active" boolean DEFAULT true NOT NULL,
 "created_by" uuid,
 "updated_by" uuid,
 "created_at" timestamp with time zone DEFAULT now() NOT NULL,
 "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
 "image_data" text DEFAULT ''::text NOT NULL
);

CREATE TABLE public."store_sales" (
 "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "gym_id" uuid NOT NULL,
 "product_id" bigint NOT NULL,
 "product_name" text NOT NULL,
 "product_sku" text DEFAULT ''::text NOT NULL,
 "quantity" integer NOT NULL,
 "unit_price" bigint NOT NULL,
 "total_amount" bigint NOT NULL,
 "payment_method" text DEFAULT 'EFECTIVO'::text NOT NULL,
 "payment_reference" text DEFAULT ''::text NOT NULL,
 "customer_name" text DEFAULT ''::text NOT NULL,
 "notes" text DEFAULT ''::text NOT NULL,
 "sold_by" uuid,
 "sold_at" timestamp with time zone DEFAULT now() NOT NULL,
 "sale_status" text DEFAULT 'posted'::text NOT NULL,
 "sale_revision" bigint DEFAULT 0 NOT NULL,
 "sale_changed_at" timestamp with time zone,
 "sale_changed_by" uuid,
 "sale_change_reason" text
);

CREATE TABLE public."accounting_expenses" (
 "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "gym_id" uuid NOT NULL,
 "expense_date" date NOT NULL,
 "category" text NOT NULL,
 "description" text NOT NULL,
 "vendor" text DEFAULT ''::text NOT NULL,
 "amount" bigint NOT NULL,
 "payment_method" text DEFAULT 'Efectivo'::text NOT NULL,
 "payment_reference" text DEFAULT ''::text NOT NULL,
 "receipt_reference" text DEFAULT ''::text NOT NULL,
 "notes" text DEFAULT ''::text NOT NULL,
 "recorded_by" uuid,
 "created_at" timestamp with time zone DEFAULT now() NOT NULL,
 "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."gyms" (
 "id" uuid DEFAULT gen_random_uuid() NOT NULL,
 "name" text NOT NULL,
 "join_code" uuid DEFAULT gen_random_uuid() NOT NULL,
 "created_by" uuid NOT NULL,
 "created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."gym_users" (
 "gym_id" uuid NOT NULL,
 "user_id" uuid NOT NULL,
 "role" text DEFAULT 'admin'::text NOT NULL,
 "created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."audit_logs" (
 "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "gym_id" uuid NOT NULL,
 "actor_user_id" uuid,
 "actor_email" text DEFAULT 'Sistema'::text NOT NULL,
 "actor_role" text DEFAULT 'system'::text NOT NULL,
 "action" text NOT NULL,
 "entity_type" text NOT NULL,
 "entity_id" text,
 "summary" text DEFAULT ''::text NOT NULL,
 "details" jsonb DEFAULT '{}'::jsonb NOT NULL,
 "created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."app_clock" (
 "id" smallint NOT NULL,
 "current_day" date NOT NULL,
 "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."classes" (
 "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "gym_id" uuid NOT NULL,
 "trainer_id" bigint,
 "name" text NOT NULL,
 "starts_at" timestamp with time zone NOT NULL,
 "capacity" integer DEFAULT 1 NOT NULL,
 "notes" text DEFAULT ''::text,
 "active" boolean DEFAULT true NOT NULL,
 "status" text DEFAULT 'PROGRAMADA'::text NOT NULL
);

CREATE TABLE public."reservations" (
 "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "gym_id" uuid NOT NULL,
 "class_id" bigint NOT NULL,
 "client_id" bigint NOT NULL,
 "status" text DEFAULT 'RESERVADA'::text NOT NULL,
 "created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."marketing_settings" (
 "gym_id" uuid NOT NULL,
 "whatsapp_enabled" boolean DEFAULT false NOT NULL,
 "birthday_enabled" boolean DEFAULT true NOT NULL,
 "expiring_enabled" boolean DEFAULT true NOT NULL,
 "expired_enabled" boolean DEFAULT true NOT NULL,
 "send_hour" smallint DEFAULT 9 NOT NULL,
 "warning_days" smallint DEFAULT 5 NOT NULL,
 "timezone" text DEFAULT 'America/Bogota'::text NOT NULL,
 "language_code" text DEFAULT 'es_CO'::text NOT NULL,
 "default_country_code" text DEFAULT '57'::text NOT NULL,
 "birthday_template" text DEFAULT 'ztattuz_cumpleanos'::text NOT NULL,
 "expiring_template" text DEFAULT 'ztattuz_membresia_vence'::text NOT NULL,
 "expired_template" text DEFAULT 'ztattuz_membresia_vencida'::text NOT NULL,
 "birthday_extra" text DEFAULT 'Esperamos que disfrutes tu día. Pregunta por tu beneficio de cumpleaños.'::text NOT NULL,
 "expiring_extra" text DEFAULT 'Renueva a tiempo para continuar entrenando sin interrupciones.'::text NOT NULL,
 "expired_extra" text DEFAULT 'Te esperamos para renovar y volver a entrenar con nosotros.'::text NOT NULL,
 "waba_id" text DEFAULT ''::text NOT NULL,
 "phone_number_id" text DEFAULT ''::text NOT NULL,
 "graph_api_version" text DEFAULT 'v23.0'::text NOT NULL,
 "last_worker_at" timestamp with time zone,
 "last_error" text DEFAULT ''::text NOT NULL,
 "updated_by" uuid,
 "created_at" timestamp with time zone DEFAULT now() NOT NULL,
 "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."marketing_messages" (
 "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "gym_id" uuid NOT NULL,
 "client_id" bigint,
 "automation_type" text NOT NULL,
 "source_date" date NOT NULL,
 "client_name" text DEFAULT ''::text NOT NULL,
 "phone" text NOT NULL,
 "template_name" text NOT NULL,
 "language_code" text DEFAULT 'es_CO'::text NOT NULL,
 "template_parameters" jsonb DEFAULT '[]'::jsonb NOT NULL,
 "status" text DEFAULT 'PENDING'::text NOT NULL,
 "attempts" smallint DEFAULT 0 NOT NULL,
 "whatsapp_message_id" text DEFAULT ''::text NOT NULL,
 "error_message" text DEFAULT ''::text NOT NULL,
 "scheduled_for" timestamp with time zone DEFAULT now() NOT NULL,
 "created_at" timestamp with time zone DEFAULT now() NOT NULL,
 "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
 "sent_at" timestamp with time zone
);

CREATE TABLE public."memberships" (
 "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "gym_id" uuid NOT NULL,
 "client_id" bigint NOT NULL,
 "plan_id" bigint NOT NULL,
 "start_date" date NOT NULL,
 "end_date" date NOT NULL,
 "entry_limit" integer,
 "amount_paid" bigint DEFAULT 0 NOT NULL,
 "payment_method" text DEFAULT 'Efectivo'::text NOT NULL,
 "payment_reference" text DEFAULT ''::text,
 "notes" text DEFAULT ''::text,
 "paid_at" timestamp with time zone DEFAULT now() NOT NULL,
 "amount" bigint DEFAULT 0 NOT NULL,
 "recorded_by" uuid,
 "payment_status" text DEFAULT 'posted'::text NOT NULL,
 "payment_revision" bigint DEFAULT 0 NOT NULL,
 "payment_changed_at" timestamp with time zone,
 "payment_changed_by" uuid,
 "payment_change_reason" text
);

