CREATE INDEX idx_clients_whatsapp_opt_in ON public.clients USING btree (gym_id, whatsapp_opt_in) WHERE (whatsapp_opt_in = true);

CREATE UNIQUE INDEX clients_gym_biometric_identifier_unique ON public.clients USING btree (gym_id, upper(TRIM(BOTH FROM biometric_identifier))) WHERE ((biometric_identifier IS NOT NULL) AND (TRIM(BOTH FROM biometric_identifier) <> ''::text));

CREATE INDEX clients_gym_biometric_search_idx ON public.clients USING btree (gym_id, biometric_identifier);

CREATE INDEX idx_checkins_gym_result_date ON public.checkins USING btree (gym_id, result, checkin_at DESC);

CREATE INDEX idx_checkins_membership ON public.checkins USING btree (membership_id);

CREATE INDEX idx_staff_invites_gym ON public.staff_invites USING btree (gym_id, created_at DESC);

CREATE INDEX idx_staff_invites_code ON public.staff_invites USING btree (code);

CREATE INDEX idx_gym_events_gym_date ON public.gym_events USING btree (gym_id, created_at DESC);

CREATE INDEX idx_staff_shifts_gym_date ON public.staff_shifts USING btree (gym_id, check_in_at DESC);

CREATE INDEX idx_staff_shifts_trainer_date ON public.staff_shifts USING btree (trainer_id, check_in_at DESC);

CREATE UNIQUE INDEX idx_staff_shifts_one_open ON public.staff_shifts USING btree (trainer_id) WHERE (check_out_at IS NULL);

CREATE UNIQUE INDEX store_products_gym_name_unique ON public.store_products USING btree (gym_id, lower(TRIM(BOTH FROM name)));

CREATE UNIQUE INDEX store_products_gym_sku_unique ON public.store_products USING btree (gym_id, lower(TRIM(BOTH FROM sku))) WHERE (TRIM(BOTH FROM sku) <> ''::text);

CREATE INDEX store_products_gym_active_name ON public.store_products USING btree (gym_id, active, name);

CREATE INDEX store_sales_gym_date ON public.store_sales USING btree (gym_id, sold_at DESC);

CREATE INDEX store_sales_gym_product ON public.store_sales USING btree (gym_id, product_id, sold_at DESC);

CREATE INDEX store_sales_gym_status_date ON public.store_sales USING btree (gym_id, sale_status, sold_at DESC);

CREATE INDEX idx_accounting_expenses_gym_date ON public.accounting_expenses USING btree (gym_id, expense_date DESC, id DESC);

CREATE INDEX idx_audit_logs_gym_date ON public.audit_logs USING btree (gym_id, created_at DESC);

CREATE INDEX idx_audit_logs_gym_action ON public.audit_logs USING btree (gym_id, action, created_at DESC);

CREATE INDEX idx_marketing_messages_gym_date ON public.marketing_messages USING btree (gym_id, created_at DESC);

CREATE INDEX idx_marketing_messages_pending ON public.marketing_messages USING btree (status, scheduled_for) WHERE (status = ANY (ARRAY['PENDING'::text, 'FAILED'::text]));

CREATE OR REPLACE FUNCTION private.audit_membership_payment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    before_row jsonb;
    after_row jsonb;
    row_data jsonb;
    actor uuid := auth.uid();
    actor_mail text;
    actor_role text;
    action_name text;
    message text;
begin
    if tg_op <> 'INSERT' then before_row := to_jsonb(old); end if;
    if tg_op <> 'DELETE' then after_row := to_jsonb(new); end if;
    row_data := coalesce(after_row, before_row);
    if tg_op = 'UPDATE' and
       (before_row - 'recorded_by' - 'updated_at') =
       (after_row - 'recorded_by' - 'updated_at') then
        return new;
    end if;
    select u.email into actor_mail from auth.users u where u.id = actor;
    select gu.role into actor_role from public.gym_users gu
        where gu.gym_id = (row_data->>'gym_id')::uuid and gu.user_id = actor;
    action_name := case
        when tg_op = 'INSERT' then 'PAGO_REGISTRADO'
        when tg_op = 'DELETE' then 'PAGO_ELIMINADO'
        when new.payment_status = 'void' and old.payment_status <> 'void'
            then 'PAGO_ANULADO'
        else 'PAGO_EDITADO'
    end;
    message := case action_name
        when 'PAGO_REGISTRADO' then 'Pago registrado'
        when 'PAGO_ELIMINADO' then 'Pago retirado de datos operativos'
        when 'PAGO_ANULADO' then 'Pago anulado'
        else 'Pago corregido'
    end || ' · cliente #' || (row_data->>'client_id') || ' · $' ||
        coalesce(row_data->>'amount', row_data->>'amount_paid', '0');
    if tg_op = 'UPDATE' then
        message := message || ' · anterior $' ||
            coalesce(before_row->>'amount', before_row->>'amount_paid', '0') ||
            ' · ' || coalesce(after_row->>'payment_change_reason', 'Actualización administrativa');
    end if;
    insert into public.audit_logs (
        gym_id, actor_user_id, actor_email, actor_role, action,
        entity_type, entity_id, summary, details
    ) values (
        (row_data->>'gym_id')::uuid, actor,
        coalesce(actor_mail, 'Sistema'), coalesce(actor_role, 'system'), action_name,
        'memberships', row_data->>'id', message,
        jsonb_build_object('before', before_row, 'after', after_row,
            'reason', case when tg_op = 'UPDATE' then after_row->>'payment_change_reason' end,
            'client_id', row_data->>'client_id', 'payment_revision', row_data->'payment_revision')
    );
    if tg_op = 'DELETE' then return old; end if;
    return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.audit_store_product()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_row jsonb;
    v_action text;
    v_actor uuid;
    v_summary text;
    v_details jsonb;
begin
    v_row := case
        when tg_op = 'DELETE' then to_jsonb(old)
        else to_jsonb(new)
    end;
    v_action := case tg_op
        when 'INSERT' then 'PRODUCTO_CREADO'
        when 'UPDATE' then 'PRODUCTO_EDITADO'
        else 'PRODUCTO_ELIMINADO'
    end;
    v_actor := coalesce(
        nullif(v_row ->> 'updated_by', '')::uuid,
        nullif(v_row ->> 'created_by', '')::uuid,
        (select auth.uid())
    );

    if tg_op = 'UPDATE' then
        v_summary := concat(
            new.name,
            ' · Precio $', old.sale_price, ' → $', new.sale_price,
            ' · Stock ', old.stock_quantity, ' → ', new.stock_quantity
        );
        v_details := jsonb_build_object(
            'before', jsonb_build_object(
                'name', old.name,
                'sku', old.sku,
                'sale_price', old.sale_price,
                'stock_quantity', old.stock_quantity,
                'active', old.active
            ),
            'after', jsonb_build_object(
                'name', new.name,
                'sku', new.sku,
                'sale_price', new.sale_price,
                'stock_quantity', new.stock_quantity,
                'active', new.active
            )
        );
    else
        v_summary := concat(
            coalesce(v_row ->> 'name', 'Producto'),
            ' · $', coalesce(v_row ->> 'sale_price', '0'),
            ' · Stock ', coalesce(v_row ->> 'stock_quantity', '0')
        );
        v_details := jsonb_build_object(
            'name', v_row ->> 'name',
            'sku', v_row ->> 'sku',
            'sale_price', v_row ->> 'sale_price',
            'stock_quantity', v_row ->> 'stock_quantity',
            'active', v_row ->> 'active'
        );
    end if;

    perform private.insert_store_audit(
        nullif(v_row ->> 'gym_id', '')::uuid,
        v_actor,
        v_action,
        'store_products',
        v_row ->> 'id',
        v_summary,
        v_details
    );

    if tg_op = 'DELETE' then
        return old;
    end if;
    return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.audit_store_sale()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    perform private.insert_store_audit(
        new.gym_id,
        coalesce(new.sold_by, (select auth.uid())),
        'VENTA_TIENDA',
        'store_sales',
        new.id::text,
        concat(
            new.quantity, ' × ', new.product_name,
            ' · $', new.total_amount,
            ' · ', new.payment_method
        ),
        jsonb_build_object(
            'product_id', new.product_id,
            'product_name', new.product_name,
            'quantity', new.quantity,
            'unit_price', new.unit_price,
            'total_amount', new.total_amount,
            'payment_method', new.payment_method,
            'customer_name', new.customer_name
        )
    );
    return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.audit_store_sale_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    actor uuid := (select auth.uid());
    actor_email text;
    actor_role text;
    action_name text;
    summary_text text;
begin
    begin
        actor_email := coalesce(
            nullif((select auth.jwt() ->> 'email'), ''),
            case
                when actor is null then 'Sistema'
                else 'Usuario ' || left(actor::text, 8)
            end
        );
    exception when others then
        actor_email := case
            when actor is null then 'Sistema'
            else 'Usuario ' || left(actor::text, 8)
        end;
    end;

    select coalesce(gu.role, 'authenticated')
    into actor_role
    from public.gym_users gu
    where gu.gym_id = new.gym_id
      and gu.user_id = actor
    limit 1;

    actor_role := coalesce(actor_role, 'system');
    action_name := case
        when new.sale_status = 'void'
            and old.sale_status <> 'void' then 'VENTA_ANULADA'
        else 'VENTA_EDITADA'
    end;
    summary_text := case
        when action_name = 'VENTA_ANULADA' then 'Venta anulada'
        else 'Venta corregida'
    end || ' · ' || new.quantity || ' × ' || new.product_name
        || ' · $' || new.total_amount;

    insert into public.audit_logs(
        gym_id,
        actor_user_id,
        actor_email,
        actor_role,
        action,
        entity_type,
        entity_id,
        summary,
        details
    )
    values (
        new.gym_id,
        actor,
        actor_email,
        actor_role,
        action_name,
        'store_sales',
        new.id::text,
        summary_text,
        jsonb_build_object(
            'before', to_jsonb(old),
            'after', to_jsonb(new),
            'reason', new.sale_change_reason
        )
    );
    return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.client_belongs_to_gym(p_client_id bigint, p_gym_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
    select exists (
        select 1
        from public.clients c
        where c.id = p_client_id
          and c.gym_id = p_gym_id
    );
$function$
;

CREATE OR REPLACE FUNCTION private.insert_store_audit(p_gym_id uuid, p_actor_user_id uuid, p_action text, p_entity_type text, p_entity_id text, p_summary text, p_details jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_actor_email text;
    v_actor_role text;
begin
    select coalesce(gu.role, 'authenticated')
    into v_actor_role
    from public.gym_users gu
    where gu.gym_id = p_gym_id
      and gu.user_id = p_actor_user_id
    limit 1;

    v_actor_role := coalesce(v_actor_role, 'system');

    begin
        v_actor_email := coalesce(
            nullif(auth.jwt() ->> 'email', ''),
            case
                when p_actor_user_id is null then 'Sistema'
                else 'Usuario ' || left(p_actor_user_id::text, 8)
            end
        );
    exception when others then
        v_actor_email := case
            when p_actor_user_id is null then 'Sistema'
            else 'Usuario ' || left(p_actor_user_id::text, 8)
        end;
    end;

    insert into public.audit_logs(
        gym_id,
        actor_user_id,
        actor_email,
        actor_role,
        action,
        entity_type,
        entity_id,
        summary,
        details
    )
    values (
        p_gym_id,
        p_actor_user_id,
        v_actor_email,
        v_actor_role,
        p_action,
        p_entity_type,
        p_entity_id,
        trim(coalesce(p_summary, '')),
        coalesce(p_details, '{}'::jsonb)
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION private.membership_snapshot_json(p_gym_id uuid, p_client_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_client record;
    v_membership_id bigint;
    v_start_date date;
    v_end_date date;
    v_entry_limit bigint;
    v_entries_used bigint := 0;
    v_plan_name text := 'Sin plan';
    v_today date := public.ztattuz_today();
    v_allowed boolean := false;
    v_status text := 'VENCIDO';
begin
    select
        c.id,
        c.document,
        c.first_name,
        c.last_name,
        c.phone,
        c.email,
        coalesce(c.birthdate, c.birth_date) as birthdate,
        c.active
    into v_client
    from public.clients c
    where c.id = p_client_id
      and c.gym_id = p_gym_id;

    if not found then
        raise exception 'Cliente no encontrado.' using errcode = 'P0002';
    end if;

    select
        m.id,
        m.start_date,
        m.end_date,
        coalesce(m.entry_limit, p.entry_limit),
        coalesce(p.name, 'Sin plan')
    into
        v_membership_id,
        v_start_date,
        v_end_date,
        v_entry_limit,
        v_plan_name
    from public.memberships m
    left join public.plans p
      on p.id = m.plan_id
     and p.gym_id = m.gym_id
    where m.gym_id = p_gym_id AND m.payment_status = 'posted' /* ZTATTUZ_PAYMENT_VOID_FILTER_V1 */
      and m.client_id = p_client_id
    order by
        case
            when v_today between m.start_date and m.end_date then 0
            else 1
        end,
        m.end_date desc,
        m.id desc
    limit 1;

    if v_membership_id is not null and v_entry_limit is not null then
        select count(*)
        into v_entries_used
        from public.checkins ch
        where ch.gym_id = p_gym_id
          and ch.membership_id = v_membership_id
          and ch.result = 'PERMITIDA';
    end if;

    if not coalesce(v_client.active, true) then
        v_status := 'INACTIVO';
    elsif v_membership_id is null then
        v_status := 'VENCIDO';
    elsif not (v_today between v_start_date and v_end_date) then
        v_status := 'VENCIDO';
    elsif v_entry_limit is not null
          and v_entries_used >= v_entry_limit then
        v_status := 'SIN ENTRADAS';
    else
        v_status := 'AL DÍA';
        v_allowed := true;
    end if;

    return jsonb_build_object(
        'id', v_client.id,
        'document', v_client.document,
        'first_name', v_client.first_name,
        'last_name', v_client.last_name,
        'client_name', trim(
            concat_ws(' ', v_client.first_name, v_client.last_name)
        ),
        'phone', coalesce(v_client.phone, ''),
        'email', coalesce(v_client.email, ''),
        'birthdate', coalesce(v_client.birthdate::text, ''),
        'active', coalesce(v_client.active, true),
        'status', v_status,
        'allowed', v_allowed,
        'membership_id', v_membership_id,
        'membership_start', coalesce(v_start_date::text, ''),
        'membership_end', coalesce(v_end_date::text, ''),
        'plan_name', v_plan_name,
        'entry_limit', v_entry_limit,
        'entries_used', v_entries_used,
        'entries_remaining', case
            when v_entry_limit is null then null
            else greatest(v_entry_limit - v_entries_used, 0)
        end
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION private.notify_gym_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_gym_id uuid;
begin
    if tg_op = 'DELETE' then
        v_gym_id := old.gym_id;
    else
        v_gym_id := new.gym_id;
    end if;

    insert into public.gym_events(gym_id, event_type)
    values (v_gym_id, tg_table_name || ':' || lower(tg_op));

    if tg_op = 'DELETE' then
        return old;
    end if;

    return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.plan_belongs_to_gym(p_plan_id bigint, p_gym_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
    select exists (
        select 1
        from public.plans p
        where p.id = p_plan_id
          and p.gym_id = p_gym_id
          and p.active = true
    );
$function$
;

CREATE OR REPLACE FUNCTION private.user_has_gym_role(p_gym_id uuid, p_roles text[])
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
    select exists (
        select 1
        from public.gym_users gu
        where gu.user_id = (select auth.uid())
          and gu.gym_id = p_gym_id
          and gu.role = any(p_roles)
    );
$function$
;

CREATE OR REPLACE FUNCTION private.write_audit_log()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_row jsonb;
    v_old_row jsonb;
    v_gym_id uuid;
    v_actor_user_id uuid;
    v_actor_email text := 'Sistema';
    v_actor_role text := 'system';
    v_action text;
    v_entity_id text;
    v_summary text := '';
    v_details jsonb := '{}'::jsonb;
begin
    if tg_op = 'DELETE' then
        v_row := to_jsonb(old);
    else
        v_row := to_jsonb(new);
    end if;

    if tg_op = 'UPDATE' then
        v_old_row := to_jsonb(old);

        -- El envoltorio de pagos completa recorded_by justo después
        -- de insertar. Ese cambio técnico no debe crear un log duplicado.
        if tg_table_name = 'memberships'
           and (v_row - 'recorded_by') = (v_old_row - 'recorded_by') then
            return new;
        end if;
    end if;

    v_gym_id := nullif(v_row ->> 'gym_id', '')::uuid;
    v_actor_user_id := coalesce(
        nullif(v_row ->> 'recorded_by', '')::uuid,
        (select auth.uid())
    );

    if v_actor_user_id is not null then
        select coalesce(gu.role, 'authenticated')
        into v_actor_role
        from public.gym_users gu
        where gu.gym_id = v_gym_id
          and gu.user_id = v_actor_user_id
        limit 1;

        v_actor_role := coalesce(v_actor_role, 'authenticated');
    end if;

    begin
        v_actor_email := coalesce(
            nullif(auth.jwt() ->> 'email', ''),
            case
                when v_actor_user_id is null then 'Sistema'
                else 'Usuario ' || left(v_actor_user_id::text, 8)
            end
        );
    exception when others then
        v_actor_email := case
            when v_actor_user_id is null then 'Sistema'
            else 'Usuario ' || left(v_actor_user_id::text, 8)
        end;
    end;

    if tg_table_name = 'memberships' then
        v_action := case tg_op
            when 'INSERT' then 'PAGO_REGISTRADO'
            when 'UPDATE' then 'PAGO_EDITADO'
            else 'PAGO_ELIMINADO'
        end;
        v_entity_id := v_row ->> 'id';
        v_summary := concat(
            'Pago de $',
            coalesce(v_row ->> 'amount', v_row ->> 'amount_paid', '0'),
            ' para el cliente #',
            coalesce(v_row ->> 'client_id', '—')
        );
        v_details := jsonb_build_object(
            'client_id', v_row ->> 'client_id',
            'plan_id', v_row ->> 'plan_id',
            'start_date', v_row ->> 'start_date',
            'end_date', v_row ->> 'end_date',
            'amount', coalesce(
                v_row ->> 'amount',
                v_row ->> 'amount_paid',
                '0'
            ),
            'payment_method', coalesce(
                v_row ->> 'payment_method',
                ''
            )
        );
    elsif tg_table_name = 'checkins' then
        v_action := 'ENTRADA_REGISTRADA';
        v_entity_id := v_row ->> 'id';
        v_summary := concat(
            'Entrada ',
            coalesce(v_row ->> 'result', 'registrada'),
            ' para el cliente #',
            coalesce(v_row ->> 'client_id', '—')
        );
        v_details := jsonb_build_object(
            'client_id', v_row ->> 'client_id',
            'result', v_row ->> 'result',
            'method', v_row ->> 'method'
        );
    elsif tg_table_name = 'clients' then
        v_action := case tg_op
            when 'INSERT' then 'CLIENTE_CREADO'
            when 'UPDATE' then 'CLIENTE_EDITADO'
            else 'CLIENTE_ELIMINADO'
        end;
        v_entity_id := v_row ->> 'id';
        v_summary := concat(
            coalesce(v_row ->> 'first_name', ''),
            ' ',
            coalesce(v_row ->> 'last_name', ''),
            ' · ',
            coalesce(v_row ->> 'document', '')
        );
        v_details := jsonb_build_object(
            'document', v_row ->> 'document',
            'client_name', trim(concat_ws(
                ' ',
                v_row ->> 'first_name',
                v_row ->> 'last_name'
            ))
        );
    elsif tg_table_name = 'plans' then
        v_action := case tg_op
            when 'INSERT' then 'PLAN_CREADO'
            when 'UPDATE' then 'PLAN_EDITADO'
            else 'PLAN_ELIMINADO'
        end;
        v_entity_id := v_row ->> 'id';
        v_summary := concat(
            coalesce(v_row ->> 'name', 'Plan'),
            ' · $',
            coalesce(v_row ->> 'price', '0')
        );
        v_details := jsonb_build_object(
            'name', v_row ->> 'name',
            'duration_days', v_row ->> 'duration_days',
            'price', v_row ->> 'price',
            'active', v_row ->> 'active'
        );
    elsif tg_table_name = 'gym_users' then
        v_action := case tg_op
            when 'INSERT' then 'USUARIO_AGREGADO'
            when 'UPDATE' then 'USUARIO_EDITADO'
            else 'USUARIO_ELIMINADO'
        end;
        v_entity_id := v_row ->> 'user_id';
        v_summary := concat(
            'Usuario ',
            left(coalesce(v_row ->> 'user_id', ''), 8),
            ' · ',
            coalesce(v_row ->> 'role', '')
        );
        v_details := jsonb_build_object(
            'user_id', v_row ->> 'user_id',
            'role', v_row ->> 'role'
        );
    else
        if tg_op = 'DELETE' then
            return old;
        end if;

        return new;
    end if;

    insert into public.audit_logs(
        gym_id,
        actor_user_id,
        actor_email,
        actor_role,
        action,
        entity_type,
        entity_id,
        summary,
        details
    )
    values (
        v_gym_id,
        v_actor_user_id,
        v_actor_email,
        v_actor_role,
        v_action,
        tg_table_name,
        v_entity_id,
        trim(v_summary),
        v_details
    );

    if tg_op = 'DELETE' then
        return old;
    end if;

    return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.write_staff_accounting_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_row jsonb;
    v_gym_id uuid;
    v_actor uuid;
    v_email text;
    v_role text;
    v_action text;
    v_summary text;
begin
    v_row := case
        when tg_op = 'DELETE' then to_jsonb(old)
        else to_jsonb(new)
    end;
    v_gym_id := (v_row ->> 'gym_id')::uuid;
    v_actor := coalesce(
        nullif(v_row ->> 'recorded_by', '')::uuid,
        nullif(v_row ->> 'created_by', '')::uuid,
        (select auth.uid())
    );

    select coalesce(gu.role, 'authenticated')
    into v_role
    from public.gym_users gu
    where gu.gym_id = v_gym_id
      and gu.user_id = v_actor
    limit 1;

    v_role := coalesce(v_role, 'system');
    v_email := coalesce(
        nullif(auth.jwt() ->> 'email', ''),
        case
            when v_actor is null then 'Sistema'
            else 'Usuario ' || left(v_actor::text, 8)
        end
    );

    if tg_table_name = 'accounting_expenses' then
        v_action := case tg_op
            when 'INSERT' then 'EGRESO_REGISTRADO'
            when 'UPDATE' then 'EGRESO_EDITADO'
            else 'EGRESO_ELIMINADO'
        end;
        v_summary := concat(
            coalesce(v_row ->> 'category', 'Egreso'),
            ' · $', coalesce(v_row ->> 'amount', '0'),
            ' · ', coalesce(v_row ->> 'description', '')
        );
    elsif tg_table_name = 'staff_shifts' then
        v_action := case
            when tg_op = 'INSERT' then 'JORNADA_INICIADA'
            when tg_op = 'DELETE' then 'JORNADA_ELIMINADA'
            when old.check_out_at is null and new.check_out_at is not null
                then 'JORNADA_FINALIZADA'
            else 'JORNADA_EDITADA'
        end;
        v_summary := concat(
            'Entrenador #', coalesce(v_row ->> 'trainer_id', '—'),
            ' · ', coalesce(v_row ->> 'check_in_at', ''),
            case
                when nullif(v_row ->> 'check_out_at', '') is null
                    then ' · jornada activa'
                else ' · salida ' || (v_row ->> 'check_out_at')
            end
        );
    elsif tg_table_name = 'trainers' then
        v_action := case tg_op
            when 'INSERT' then 'ENTRENADOR_CREADO'
            when 'UPDATE' then 'ENTRENADOR_EDITADO'
            else 'ENTRENADOR_ELIMINADO'
        end;
        v_summary := concat(
            coalesce(v_row ->> 'name', 'Entrenador'),
            ' · $', coalesce(v_row ->> 'hourly_rate', '0'), '/hora'
        );
    else
        if tg_op = 'DELETE' then
            return old;
        end if;
        return new;
    end if;

    insert into public.audit_logs(
        gym_id,
        actor_user_id,
        actor_email,
        actor_role,
        action,
        entity_type,
        entity_id,
        summary,
        details
    )
    values (
        v_gym_id,
        v_actor,
        v_email,
        v_role,
        v_action,
        tg_table_name,
        v_row ->> 'id',
        trim(v_summary),
        v_row
    );

    if tg_op = 'DELETE' then
        return old;
    end if;

    return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.ztattuz_import_insert(p_table text, p_gym_id uuid, p_row jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
    v_row jsonb;
    v_columns text;
    v_values text;
    v_new_id bigint;
begin
    if p_table <> all(array[
        'clients',
        'plans',
        'memberships',
        'checkins',
        'store_products',
        'store_sales',
        'accounting_expenses',
        'trainers',
        'staff_shifts',
        'routines',
        'exercises',
        'classes',
        'reservations',
        'marketing_messages'
    ]) then
        raise exception 'Tabla de importación no permitida: %', p_table;
    end if;

    v_row := (coalesce(p_row, '{}'::jsonb) - 'id' - '__excel_row')
        || jsonb_build_object('gym_id', p_gym_id);

    select
        string_agg(format('%I', attribute.attname), ', ' order by attribute.attnum),
        string_agg(format('record.%I', attribute.attname), ', ' order by attribute.attnum)
    into v_columns, v_values
    from pg_attribute attribute
    where attribute.attrelid = format('public.%I', p_table)::regclass
      and attribute.attnum > 0
      and not attribute.attisdropped
      and attribute.attname <> 'id'
      and attribute.attgenerated = ''
      and attribute.attidentity = ''
      and v_row ? attribute.attname;

    if v_columns is null then
        raise exception 'La fila de % no contiene columnas válidas.', p_table;
    end if;

    execute format(
        'insert into public.%1$I (%2$s) '
        'select %3$s '
        'from jsonb_populate_record(null::public.%1$I, $1) as record '
        'returning id',
        p_table,
        v_columns,
        v_values
    )
    using v_row
    into v_new_id;

    return v_new_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.add_membership_accumulating(p_gym_id uuid, p_client_id bigint, p_plan_id bigint, p_requested_start date, p_amount bigint, p_payment_method text, p_payment_reference text, p_notes text)
 RETURNS TABLE(membership_id bigint, start_date date, end_date date)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_user_id uuid := (select auth.uid());
    v_today date := public.ztattuz_today();
    v_requested_start date;
    v_duration_days integer;
    v_entry_limit bigint;
    v_last_end_date date;
    v_start_date date;
    v_end_date date;
    v_membership_id bigint;
begin
    if not private.user_has_gym_role(
        p_gym_id,
        array['admin', 'receptionist']::text[]
    ) then
        raise exception 'No tienes permiso para registrar pagos.'
            using errcode = '42501';
    end if;

    if not private.client_belongs_to_gym(
        p_client_id,
        p_gym_id
    ) then
        raise exception 'El cliente no pertenece al gimnasio.'
            using errcode = '23503';
    end if;

    select
        greatest(p.duration_days, 1),
        p.entry_limit
    into
        v_duration_days,
        v_entry_limit
    from public.plans p
    where p.id = p_plan_id
      and p.gym_id = p_gym_id
      and p.active = true;

    if not found then
        raise exception 'El plan no existe o está desactivado.'
            using errcode = '23503';
    end if;

    if coalesce(p_amount, 0) < 0 then
        raise exception 'El valor pagado no puede ser negativo.'
            using errcode = '22023';
    end if;

    -- Impide que dos pagos simultáneos creen fechas superpuestas.
    perform pg_catalog.pg_advisory_xact_lock(p_client_id);

    v_requested_start := coalesce(
        p_requested_start,
        v_today
    );

    select max(m.end_date)
    into v_last_end_date
    from public.memberships m
    left join public.plans current_plan
      on current_plan.id = m.plan_id
     and current_plan.gym_id = m.gym_id
    where m.gym_id = p_gym_id AND m.payment_status = 'posted' /* ZTATTUZ_PAYMENT_VOID_FILTER_V1 */
      and m.client_id = p_client_id
      and m.end_date >= v_today
      and (
          coalesce(
              m.entry_limit,
              current_plan.entry_limit
          ) is null
          or (
              select count(*)
              from public.checkins ch
              where ch.gym_id = p_gym_id
                and ch.client_id = p_client_id
                and ch.membership_id = m.id
                and ch.result = 'PERMITIDA'
          ) < coalesce(
              m.entry_limit,
              current_plan.entry_limit
          )
      );

    v_start_date := case
        when v_last_end_date is null then v_requested_start
        else greatest(
            v_requested_start,
            v_last_end_date + 1
        )
    end;

    v_end_date := (
        v_start_date + (v_duration_days - 1)
    );

    insert into public.memberships(
        gym_id,
        client_id,
        plan_id,
        start_date,
        end_date,
        entry_limit,
        amount,
        amount_paid,
        payment_method,
        payment_reference,
        notes,
        recorded_by
    )
    values (
        p_gym_id,
        p_client_id,
        p_plan_id,
        v_start_date,
        v_end_date,
        v_entry_limit,
        p_amount,
        p_amount,
        coalesce(
            nullif(trim(p_payment_method), ''),
            'Efectivo'
        ),
        trim(coalesce(p_payment_reference, '')),
        trim(coalesce(p_notes, '')),
        v_user_id
    )
    returning id into v_membership_id;

    return query
    select
        v_membership_id,
        v_start_date,
        v_end_date;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.add_membership_accumulating_internal(p_gym_id uuid, p_client_id bigint, p_plan_id bigint, p_requested_start date, p_amount bigint, p_payment_method text, p_payment_reference text DEFAULT ''::text, p_notes text DEFAULT ''::text)
 RETURNS TABLE(membership_id bigint, effective_start date, effective_end date)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
    v_duration integer;
    v_entry_limit integer;
    v_latest_end date;
    v_start date;
    v_end date;
    v_membership_id bigint;
begin
    if auth.uid() is null
       or not public.is_gym_member(p_gym_id) then
        raise exception 'No tienes acceso a este gimnasio.';
    end if;

    perform pg_advisory_xact_lock(p_client_id);

    select duration_days, entry_limit
    into v_duration, v_entry_limit
    from public.plans
    where id = p_plan_id
      and gym_id = p_gym_id
      and active = true;

    if v_duration is null then
        raise exception 'El plan no existe o está inactivo.';
    end if;

    if not exists (
        select 1
        from public.clients
        where id = p_client_id
          and gym_id = p_gym_id
    ) then
        raise exception 'El cliente no existe.';
    end if;

    select max(end_date)
    into v_latest_end
    from public.memberships
    where gym_id = p_gym_id
      and client_id = p_client_id;

    v_start := p_requested_start;

    if v_latest_end is not null
       and v_latest_end >= v_start then
        v_start := v_latest_end + 1;
    end if;

    v_end := v_start + (v_duration - 1);

    insert into public.memberships (
        gym_id,
        client_id,
        plan_id,
        start_date,
        end_date,
        entry_limit,
        amount,
        amount_paid,
        payment_method,
        payment_reference,
        notes
    )
    values (
        p_gym_id,
        p_client_id,
        p_plan_id,
        v_start,
        v_end,
        v_entry_limit,
        p_amount,
        p_amount,
        p_payment_method,
        trim(coalesce(p_payment_reference, '')),
        trim(coalesce(p_notes, ''))
    )
    returning id into v_membership_id;

    return query
    select v_membership_id, v_start, v_end;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_accounting_expenses(p_gym_id uuid, p_date_from date, p_date_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_result jsonb;
begin
    if not private.user_has_gym_role(
        p_gym_id,
        array['admin']::text[]
    ) then
        raise exception 'La contabilidad es exclusiva del administrador.'
            using errcode = '42501';
    end if;

    if p_date_from is null or p_date_to is null or p_date_from > p_date_to then
        raise exception 'El período contable no es válido.'
            using errcode = '22023';
    end if;

    with expenses as (
        select
            e.*,
            coalesce(
                nullif(a.actor_email, ''),
                case
                    when e.recorded_by is null then 'Sistema'
                    else 'Usuario ' || left(e.recorded_by::text, 8)
                end
            ) as actor_email,
            coalesce(nullif(a.actor_role, ''), 'admin') as actor_role
        from public.accounting_expenses e
        left join lateral (
            select al.actor_email, al.actor_role
            from public.audit_logs al
            where al.gym_id = e.gym_id
              and al.entity_type = 'accounting_expenses'
              and al.entity_id = e.id::text
              and al.action = 'EGRESO_REGISTRADO'
            order by al.created_at asc, al.id asc
            limit 1
        ) a on true
        where e.gym_id = p_gym_id
          and e.expense_date between p_date_from and p_date_to
    )
    select jsonb_build_object(
        'total_expenses', coalesce((select sum(amount) from expenses), 0),
        'expense_count', (select count(*) from expenses),
        'by_category', coalesce((
            select jsonb_agg(jsonb_build_object(
                'label', grouped.category,
                'count', grouped.expense_count,
                'total', grouped.total
            ) order by grouped.total desc, grouped.category)
            from (
                select category, count(*) expense_count, sum(amount) total
                from expenses
                group by category
            ) grouped
        ), '[]'::jsonb),
        'expenses', coalesce((
            select jsonb_agg(jsonb_build_object(
                'id', e.id,
                'expense_date', e.expense_date,
                'category', e.category,
                'description', e.description,
                'vendor', e.vendor,
                'amount', e.amount,
                'payment_method', e.payment_method,
                'payment_reference', e.payment_reference,
                'receipt_reference', e.receipt_reference,
                'notes', e.notes,
                'actor_email', e.actor_email,
                'actor_role', e.actor_role,
                'created_at', e.created_at
            ) order by e.expense_date desc, e.id desc)
            from expenses e
        ), '[]'::jsonb)
    ) into v_result;

    return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_list_store_products(p_gym_id uuid, p_search text DEFAULT ''::text, p_include_inactive boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_search text := trim(coalesce(p_search, ''));
    v_result jsonb;
begin
    if not private.user_has_gym_role(
        p_gym_id,
        array['admin']::text[]
    ) then
        raise exception 'La tienda administrativa es exclusiva del administrador.'
            using errcode = '42501';
    end if;

    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id', p.id,
                'name', p.name,
                'sku', p.sku,
                'sale_price', p.sale_price,
                'stock_quantity', p.stock_quantity,
                'low_stock_threshold', p.low_stock_threshold,
                'active', p.active,
                'image_data', coalesce(p.image_data, ''),
                'stock_status', case
                    when not p.active then 'INACTIVO'
                    when p.stock_quantity = 0 then 'AGOTADO'
                    when p.stock_quantity <= p.low_stock_threshold
                        then 'POCAS UNIDADES'
                    else 'DISPONIBLE'
                end,
                'created_at', p.created_at,
                'updated_at', p.updated_at
            )
            order by p.active desc, p.name
        ),
        '[]'::jsonb
    )
    into v_result
    from public.store_products p
    where p.gym_id = p_gym_id
      and (p_include_inactive or p.active)
      and (
          v_search = ''
          or p.name ilike '%' || v_search || '%'
          or p.sku ilike '%' || v_search || '%'
      );

    return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_list_store_sales(p_gym_id uuid, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    result jsonb;
begin
    if not private.user_has_gym_role(p_gym_id, array['admin']::text[]) then
        raise exception 'Las ventas son exclusivas del administrador.'
            using errcode = '42501';
    end if;

    select coalesce(jsonb_agg(
        jsonb_build_object(
            'id', recent.id,
            'product_id', recent.product_id,
            'product_name', recent.product_name,
            'product_sku', recent.product_sku,
            'quantity', recent.quantity,
            'unit_price', recent.unit_price,
            'total_amount', recent.total_amount,
            'payment_method', recent.payment_method,
            'payment_reference', recent.payment_reference,
            'customer_name', recent.customer_name,
            'notes', recent.notes,
            'sold_by', recent.sold_by,
            'sold_at', recent.sold_at,
            'sale_status', recent.sale_status,
            'sale_revision', recent.sale_revision,
            'sale_changed_at', recent.sale_changed_at,
            'sale_change_reason', recent.sale_change_reason,
            'actor_email', recent.actor_email,
            'actor_role', recent.actor_role
        ) order by recent.sold_at desc, recent.id desc
    ), '[]'::jsonb)
    into result
    from (
        select
            s.*,
            coalesce(a.actor_email, 'Sistema') as actor_email,
            coalesce(a.actor_role, 'system') as actor_role
        from public.store_sales s
        left join lateral (
            select al.actor_email, al.actor_role
            from public.audit_logs al
            where al.gym_id = s.gym_id
              and al.entity_type = 'store_sales'
              and al.entity_id = s.id::text
              and al.action in ('VENTA_TIENDA', 'VENTA_EDITADA')
            order by al.id desc
            limit 1
        ) a on true
        where s.gym_id = p_gym_id
          and coalesce(s.sale_status, 'posted') = 'posted'
        order by s.sold_at desc, s.id desc
        limit least(greatest(coalesce(p_limit, 100), 1), 500)
    ) recent;

    return result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_replace_gym_from_excel(p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
    v_gym_id uuid;
    v_tables jsonb;
    v_row jsonb;
    v_old_id text;
    v_new_id bigint;
    v_client_id bigint;
    v_plan_id bigint;
    v_membership_id bigint;
    v_product_id bigint;
    v_trainer_id bigint;
    v_routine_id bigint;
    v_class_id bigint;
    v_image jsonb;
    v_total integer := 0;
begin
    if coalesce(p_data->>'format', '') <> 'ZTATTUZ-EXCEL-REPLACE-2' then
        raise exception 'El formato de importación no es válido.';
    end if;

    select gym_user.gym_id
    into v_gym_id
    from public.gym_users gym_user
    where gym_user.user_id = auth.uid()
      and lower(coalesce(gym_user.role::text, '')) = 'admin'
    limit 1;

    if v_gym_id is null then
        raise exception 'Solo un administrador puede reemplazar la información.'
            using errcode = '42501';
    end if;

    v_tables := coalesce(p_data->'tables', '{}'::jsonb);

    perform pg_advisory_xact_lock(
        hashtextextended('ztattuz-import-' || v_gym_id::text, 0)
    );

    create temporary table ztattuz_import_ids (
        entity text not null,
        old_id text not null,
        new_id bigint not null,
        primary key (entity, old_id)
    ) on commit drop;

    create temporary table ztattuz_product_images (
        sku text primary key,
        image_data jsonb not null
    ) on commit drop;

    insert into ztattuz_product_images (sku, image_data)
    select
        lower(trim(product.sku)),
        to_jsonb(product.image_data)
    from public.store_products product
    where product.gym_id = v_gym_id
      and nullif(trim(product.sku), '') is not null
      and product.image_data is not null
    on conflict (sku) do nothing;

    delete from public.marketing_messages where gym_id = v_gym_id;
    delete from public.staff_shifts where gym_id = v_gym_id;
    delete from public.store_sales where gym_id = v_gym_id;
    delete from public.accounting_expenses where gym_id = v_gym_id;
    delete from public.reservations where gym_id = v_gym_id;
    delete from public.exercises where gym_id = v_gym_id;
    delete from public.checkins where gym_id = v_gym_id;
    delete from public.classes where gym_id = v_gym_id;
    delete from public.routines where gym_id = v_gym_id;
    delete from public.memberships where gym_id = v_gym_id;
    delete from public.trainers where gym_id = v_gym_id;
    delete from public.clients where gym_id = v_gym_id;
    delete from public.store_products where gym_id = v_gym_id;
    delete from public.plans where gym_id = v_gym_id;

    for v_row in
        select value
        from jsonb_array_elements(
            coalesce(v_tables->'plans', '[]'::jsonb)
        )
    loop
        v_old_id := nullif(v_row->>'id', '');
        if v_old_id is null then
            raise exception 'Un plan no tiene ID interno.';
        end if;
        v_new_id := private.ztattuz_import_insert(
            'plans', v_gym_id, v_row
        );
        insert into ztattuz_import_ids values (
            'plans', v_old_id, v_new_id
        );
    end loop;

    for v_row in
        select value
        from jsonb_array_elements(
            coalesce(v_tables->'clients', '[]'::jsonb)
        )
    loop
        v_old_id := nullif(v_row->>'id', '');
        if v_old_id is null then
            raise exception 'Un cliente no tiene ID interno.';
        end if;
        v_new_id := private.ztattuz_import_insert(
            'clients', v_gym_id, v_row
        );
        insert into ztattuz_import_ids values (
            'clients', v_old_id, v_new_id
        );
    end loop;

    for v_row in
        select value
        from jsonb_array_elements(
            coalesce(v_tables->'store_products', '[]'::jsonb)
        )
    loop
        v_old_id := nullif(v_row->>'id', '');
        if v_old_id is null then
            raise exception 'Un producto no tiene ID interno.';
        end if;

        if not (v_row ? 'image_data') then
            select saved.image_data
            into v_image
            from ztattuz_product_images saved
            where saved.sku = lower(trim(v_row->>'sku'));

            if v_image is not null then
                v_row := v_row || jsonb_build_object(
                    'image_data', v_image
                );
            end if;
        end if;

        v_new_id := private.ztattuz_import_insert(
            'store_products', v_gym_id, v_row
        );
        insert into ztattuz_import_ids values (
            'store_products', v_old_id, v_new_id
        );
    end loop;

    for v_row in
        select value
        from jsonb_array_elements(
            coalesce(v_tables->'trainers', '[]'::jsonb)
        )
    loop
        v_old_id := nullif(v_row->>'id', '');
        if v_old_id is null then
            raise exception 'Un trabajador no tiene ID interno.';
        end if;
        v_new_id := private.ztattuz_import_insert(
            'trainers', v_gym_id, v_row
        );
        insert into ztattuz_import_ids values (
            'trainers', v_old_id, v_new_id
        );
    end loop;

    for v_row in
        select value
        from jsonb_array_elements(
            coalesce(v_tables->'accounting_expenses', '[]'::jsonb)
        )
    loop
        perform private.ztattuz_import_insert(
            'accounting_expenses', v_gym_id, v_row
        );
    end loop;

    for v_row in
        select value
        from jsonb_array_elements(
            coalesce(v_tables->'memberships', '[]'::jsonb)
        )
    loop
        select new_id into v_client_id
        from ztattuz_import_ids
        where entity = 'clients'
          and old_id = v_row->>'client_id';

        select new_id into v_plan_id
        from ztattuz_import_ids
        where entity = 'plans'
          and old_id = v_row->>'plan_id';

        if v_client_id is null or v_plan_id is null then
            raise exception 'Una membresía tiene relaciones inválidas.';
        end if;

        v_old_id := nullif(v_row->>'id', '');
        v_row := v_row || jsonb_build_object(
            'client_id', v_client_id,
            'plan_id', v_plan_id
        );
        v_new_id := private.ztattuz_import_insert(
            'memberships', v_gym_id, v_row
        );
        insert into ztattuz_import_ids values (
            'memberships', v_old_id, v_new_id
        );
    end loop;

    for v_row in
        select value
        from jsonb_array_elements(
            coalesce(v_tables->'routines', '[]'::jsonb)
        )
    loop
        select new_id into v_client_id
        from ztattuz_import_ids
        where entity = 'clients'
          and old_id = v_row->>'client_id';

        v_trainer_id := null;
        if nullif(v_row->>'trainer_id', '') is not null then
            select new_id into v_trainer_id
            from ztattuz_import_ids
            where entity = 'trainers'
              and old_id = v_row->>'trainer_id';
        end if;

        if v_client_id is null then
            raise exception 'Una rutina tiene un cliente inválido.';
        end if;

        v_old_id := nullif(v_row->>'id', '');
        v_row := v_row || jsonb_build_object(
            'client_id', v_client_id
        );
        if v_trainer_id is null then
            v_row := v_row - 'trainer_id';
        else
            v_row := v_row || jsonb_build_object(
                'trainer_id', v_trainer_id
            );
        end if;

        v_new_id := private.ztattuz_import_insert(
            'routines', v_gym_id, v_row
        );
        insert into ztattuz_import_ids values (
            'routines', v_old_id, v_new_id
        );
    end loop;

    for v_row in
        select value
        from jsonb_array_elements(
            coalesce(v_tables->'classes', '[]'::jsonb)
        )
    loop
        v_trainer_id := null;
        if nullif(v_row->>'trainer_id', '') is not null then
            select new_id into v_trainer_id
            from ztattuz_import_ids
            where entity = 'trainers'
              and old_id = v_row->>'trainer_id';
        end if;

        v_old_id := nullif(v_row->>'id', '');
        if v_trainer_id is null then
            v_row := v_row - 'trainer_id';
        else
            v_row := v_row || jsonb_build_object(
                'trainer_id', v_trainer_id
            );
        end if;

        v_new_id := private.ztattuz_import_insert(
            'classes', v_gym_id, v_row
        );
        insert into ztattuz_import_ids values (
            'classes', v_old_id, v_new_id
        );
    end loop;

    for v_row in
        select value
        from jsonb_array_elements(
            coalesce(v_tables->'checkins', '[]'::jsonb)
        )
    loop
        select new_id into v_client_id
        from ztattuz_import_ids
        where entity = 'clients'
          and old_id = v_row->>'client_id';

        v_membership_id := null;
        if nullif(v_row->>'membership_id', '') is not null then
            select new_id into v_membership_id
            from ztattuz_import_ids
            where entity = 'memberships'
              and old_id = v_row->>'membership_id';
        end if;

        if v_client_id is null then
            raise exception 'Una entrada tiene un cliente inválido.';
        end if;

        v_row := v_row || jsonb_build_object(
            'client_id', v_client_id
        );
        if v_membership_id is null then
            v_row := v_row - 'membership_id';
        else
            v_row := v_row || jsonb_build_object(
                'membership_id', v_membership_id
            );
        end if;

        perform private.ztattuz_import_insert(
            'checkins', v_gym_id, v_row
        );
    end loop;

    for v_row in
        select value
        from jsonb_array_elements(
            coalesce(v_tables->'exercises', '[]'::jsonb)
        )
    loop
        select new_id into v_routine_id
        from ztattuz_import_ids
        where entity = 'routines'
          and old_id = v_row->>'routine_id';

        if v_routine_id is null then
            raise exception 'Un ejercicio tiene una rutina inválida.';
        end if;

        v_row := v_row || jsonb_build_object(
            'routine_id', v_routine_id
        );
        perform private.ztattuz_import_insert(
            'exercises', v_gym_id, v_row
        );
    end loop;

    for v_row in
        select value
        from jsonb_array_elements(
            coalesce(v_tables->'reservations', '[]'::jsonb)
        )
    loop
        select new_id into v_class_id
        from ztattuz_import_ids
        where entity = 'classes'
          and old_id = v_row->>'class_id';

        select new_id into v_client_id
        from ztattuz_import_ids
        where entity = 'clients'
          and old_id = v_row->>'client_id';

        if v_class_id is null or v_client_id is null then
            raise exception 'Una reserva tiene relaciones inválidas.';
        end if;

        v_row := v_row || jsonb_build_object(
            'class_id', v_class_id,
            'client_id', v_client_id
        );
        perform private.ztattuz_import_insert(
            'reservations', v_gym_id, v_row
        );
    end loop;

    for v_row in
        select value
        from jsonb_array_elements(
            coalesce(v_tables->'store_sales', '[]'::jsonb)
        )
    loop
        select new_id into v_product_id
        from ztattuz_import_ids
        where entity = 'store_products'
          and old_id = v_row->>'product_id';

        if v_product_id is null then
            raise exception 'Una venta tiene un producto inválido.';
        end if;

        v_row := v_row || jsonb_build_object(
            'product_id', v_product_id
        );
        perform private.ztattuz_import_insert(
            'store_sales', v_gym_id, v_row
        );
    end loop;

    for v_row in
        select value
        from jsonb_array_elements(
            coalesce(v_tables->'staff_shifts', '[]'::jsonb)
        )
    loop
        select new_id into v_trainer_id
        from ztattuz_import_ids
        where entity = 'trainers'
          and old_id = v_row->>'trainer_id';

        if v_trainer_id is null then
            raise exception 'Una jornada tiene un trabajador inválido.';
        end if;

        v_row := v_row || jsonb_build_object(
            'trainer_id', v_trainer_id
        );
        perform private.ztattuz_import_insert(
            'staff_shifts', v_gym_id, v_row
        );
    end loop;

    for v_row in
        select value
        from jsonb_array_elements(
            coalesce(v_tables->'marketing_messages', '[]'::jsonb)
        )
    loop
        v_client_id := null;
        if nullif(v_row->>'client_id', '') is not null then
            select new_id into v_client_id
            from ztattuz_import_ids
            where entity = 'clients'
              and old_id = v_row->>'client_id';
        end if;

        if v_client_id is null then
            v_row := v_row - 'client_id';
        else
            v_row := v_row || jsonb_build_object(
                'client_id', v_client_id
            );
        end if;

        perform private.ztattuz_import_insert(
            'marketing_messages', v_gym_id, v_row
        );
    end loop;

    v_total :=
        jsonb_array_length(coalesce(v_tables->'clients', '[]'::jsonb))
        + jsonb_array_length(coalesce(v_tables->'plans', '[]'::jsonb))
        + jsonb_array_length(coalesce(v_tables->'memberships', '[]'::jsonb))
        + jsonb_array_length(coalesce(v_tables->'checkins', '[]'::jsonb))
        + jsonb_array_length(coalesce(v_tables->'store_products', '[]'::jsonb))
        + jsonb_array_length(coalesce(v_tables->'store_sales', '[]'::jsonb))
        + jsonb_array_length(coalesce(v_tables->'accounting_expenses', '[]'::jsonb))
        + jsonb_array_length(coalesce(v_tables->'trainers', '[]'::jsonb))
        + jsonb_array_length(coalesce(v_tables->'staff_shifts', '[]'::jsonb))
        + jsonb_array_length(coalesce(v_tables->'routines', '[]'::jsonb))
        + jsonb_array_length(coalesce(v_tables->'exercises', '[]'::jsonb))
        + jsonb_array_length(coalesce(v_tables->'classes', '[]'::jsonb))
        + jsonb_array_length(coalesce(v_tables->'reservations', '[]'::jsonb))
        + jsonb_array_length(coalesce(v_tables->'marketing_messages', '[]'::jsonb));

    return jsonb_build_object(
        'status', 'ok',
        'gym_id', v_gym_id,
        'total_rows', v_total,
        'counts', jsonb_build_object(
            'clients', jsonb_array_length(coalesce(v_tables->'clients', '[]'::jsonb)),
            'plans', jsonb_array_length(coalesce(v_tables->'plans', '[]'::jsonb)),
            'memberships', jsonb_array_length(coalesce(v_tables->'memberships', '[]'::jsonb)),
            'checkins', jsonb_array_length(coalesce(v_tables->'checkins', '[]'::jsonb)),
            'store_products', jsonb_array_length(coalesce(v_tables->'store_products', '[]'::jsonb)),
            'store_sales', jsonb_array_length(coalesce(v_tables->'store_sales', '[]'::jsonb)),
            'accounting_expenses', jsonb_array_length(coalesce(v_tables->'accounting_expenses', '[]'::jsonb)),
            'trainers', jsonb_array_length(coalesce(v_tables->'trainers', '[]'::jsonb)),
            'staff_shifts', jsonb_array_length(coalesce(v_tables->'staff_shifts', '[]'::jsonb)),
            'routines', jsonb_array_length(coalesce(v_tables->'routines', '[]'::jsonb)),
            'exercises', jsonb_array_length(coalesce(v_tables->'exercises', '[]'::jsonb)),
            'classes', jsonb_array_length(coalesce(v_tables->'classes', '[]'::jsonb)),
            'reservations', jsonb_array_length(coalesce(v_tables->'reservations', '[]'::jsonb)),
            'marketing_messages', jsonb_array_length(coalesce(v_tables->'marketing_messages', '[]'::jsonb))
        )
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_save_store_product(p_gym_id uuid, p_product_id bigint, p_name text, p_sku text, p_sale_price bigint, p_stock_quantity integer, p_low_stock_threshold integer, p_active boolean, p_image_data text DEFAULT ''::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_product_id bigint;
    v_user_id uuid := (select auth.uid());
    v_image_data text := coalesce(p_image_data, '');
begin
    if not private.user_has_gym_role(
        p_gym_id,
        array['admin']::text[]
    ) then
        raise exception 'Solo el administrador puede modificar productos.'
            using errcode = '42501';
    end if;

    if trim(coalesce(p_name, '')) = ''
       or coalesce(p_sale_price, -1) < 0
       or coalesce(p_stock_quantity, -1) < 0
       or coalesce(p_low_stock_threshold, -1) < 0 then
        raise exception 'Revisa el nombre, precio y cantidades del producto.'
            using errcode = '22023';
    end if;

    if octet_length(v_image_data) > 1000000 then
        raise exception 'La foto del producto supera el tamaño permitido.'
            using errcode = '22023';
    end if;

    if v_image_data <> ''
       and v_image_data not like 'data:image/%;base64,%' then
        raise exception 'La foto del producto no tiene un formato válido.'
            using errcode = '22023';
    end if;

    if p_product_id is null then
        insert into public.store_products(
            gym_id,
            name,
            sku,
            sale_price,
            stock_quantity,
            low_stock_threshold,
            active,
            image_data,
            created_by,
            updated_by
        )
        values (
            p_gym_id,
            trim(p_name),
            upper(trim(coalesce(p_sku, ''))),
            p_sale_price,
            p_stock_quantity,
            p_low_stock_threshold,
            coalesce(p_active, true),
            v_image_data,
            v_user_id,
            v_user_id
        )
        returning id into v_product_id;
    else
        update public.store_products
        set
            name = trim(p_name),
            sku = upper(trim(coalesce(p_sku, ''))),
            sale_price = p_sale_price,
            stock_quantity = p_stock_quantity,
            low_stock_threshold = p_low_stock_threshold,
            active = coalesce(p_active, true),
            image_data = v_image_data,
            updated_by = v_user_id,
            updated_at = now()
        where id = p_product_id
          and gym_id = p_gym_id
        returning id into v_product_id;

        if v_product_id is null then
            raise exception 'Producto no encontrado.'
                using errcode = 'P0002';
        end if;
    end if;

    return v_product_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_staff_clock(p_gym_id uuid, p_trainer_id bigint, p_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_trainer public.trainers%rowtype;
begin
    if not private.user_has_gym_role(
        p_gym_id,
        array['admin']::text[]
    ) then
        raise exception 'Solo el administrador puede controlar jornadas.'
            using errcode = '42501';
    end if;

    select t.* into v_trainer
    from public.trainers t
    where t.id = p_trainer_id
      and t.gym_id = p_gym_id
      and t.active = true;

    if not found then
        raise exception 'El trabajador no existe o está inactivo.'
            using errcode = '23503';
    end if;

    if upper(trim(p_action)) = 'IN' then
        if exists (
            select 1 from public.staff_shifts s
            where s.trainer_id = p_trainer_id
              and s.check_out_at is null
        ) then
            raise exception 'El trabajador ya tiene una jornada activa.'
                using errcode = '23505';
        end if;

        insert into public.staff_shifts(
            gym_id,
            trainer_id,
            hourly_rate_snapshot,
            recorded_by
        ) values (
            p_gym_id,
            p_trainer_id,
            v_trainer.hourly_rate,
            (select auth.uid())
        );
    elsif upper(trim(p_action)) = 'OUT' then
        update public.staff_shifts
        set check_out_at = now(), recorded_by = (select auth.uid())
        where trainer_id = p_trainer_id
          and gym_id = p_gym_id
          and check_out_at is null;

        if not found then
            raise exception 'El trabajador no tiene una jornada activa.'
                using errcode = 'P0002';
        end if;
    else
        raise exception 'La acción debe ser IN u OUT.'
            using errcode = '22023';
    end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_staff_dashboard(p_gym_id uuid, p_date_from date, p_date_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_result jsonb;
begin
    if not private.user_has_gym_role(
        p_gym_id,
        array['admin']::text[]
    ) then
        raise exception 'La información de personal es administrativa.'
            using errcode = '42501';
    end if;

    if p_date_from is null or p_date_to is null or p_date_from > p_date_to then
        raise exception 'El período de jornadas no es válido.'
            using errcode = '22023';
    end if;

    with shift_values as (
        select
            s.*,
            greatest(
                extract(epoch from (
                    coalesce(s.check_out_at, now()) - s.check_in_at
                ))::bigint,
                0
            ) as duration_seconds
        from public.staff_shifts s
        where s.gym_id = p_gym_id
          and (s.check_in_at at time zone 'America/Bogota')::date
              between p_date_from and p_date_to
    ), worker_values as (
        select
            t.*,
            coalesce((
                select sum(s.duration_seconds)
                from shift_values s
                where s.trainer_id = t.id
            ), 0)::bigint as period_seconds,
            coalesce((
                select round(sum(
                    s.duration_seconds * s.hourly_rate_snapshot / 3600.0
                ))::bigint
                from shift_values s
                where s.trainer_id = t.id
            ), 0)::bigint as estimated_pay,
            (
                select s.check_in_at
                from public.staff_shifts s
                where s.trainer_id = t.id
                  and s.check_out_at is null
                order by s.check_in_at desc
                limit 1
            ) as current_check_in
        from public.trainers t
        where t.gym_id = p_gym_id
    )
    select jsonb_build_object(
        'active_staff', (
            select count(*) from worker_values w where w.active = true
        ),
        'working_now', (
            select count(*) from worker_values w
            where w.current_check_in is not null
        ),
        'total_seconds', coalesce((
            select sum(w.period_seconds) from worker_values w
        ), 0),
        'estimated_payroll', coalesce((
            select sum(w.estimated_pay) from worker_values w
        ), 0),
        'workers', coalesce((
            select jsonb_agg(jsonb_build_object(
                'id', w.id,
                'name', w.name,
                'phone', w.phone,
                'email', w.email,
                'specialty', w.specialty,
                'hourly_rate', w.hourly_rate,
                'hire_date', w.hire_date,
                'notes', w.notes,
                'active', w.active,
                'current_check_in', w.current_check_in,
                'period_seconds', w.period_seconds,
                'estimated_pay', w.estimated_pay
            ) order by w.active desc, w.name)
            from worker_values w
        ), '[]'::jsonb),
        'shifts', coalesce((
            select jsonb_agg(jsonb_build_object(
                'id', s.id,
                'trainer_id', s.trainer_id,
                'trainer_name', t.name,
                'check_in_at', s.check_in_at,
                'check_out_at', s.check_out_at,
                'duration_seconds', s.duration_seconds,
                'hourly_rate', s.hourly_rate_snapshot,
                'estimated_pay', round(
                    s.duration_seconds * s.hourly_rate_snapshot / 3600.0
                )::bigint
            ) order by s.check_in_at desc)
            from shift_values s
            join public.trainers t on t.id = s.trainer_id
        ), '[]'::jsonb)
    ) into v_result;

    return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_store_finance(p_gym_id uuid, p_date_from date, p_date_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_from date := coalesce(
        p_date_from,
        date_trunc('month', public.ztattuz_today())::date
    );
    v_to date := coalesce(p_date_to, public.ztattuz_today());
    result jsonb;
begin
    if not private.user_has_gym_role(p_gym_id, array['admin']::text[]) then
        raise exception 'Las finanzas son exclusivas del administrador.'
            using errcode = '42501';
    end if;
    if v_from > v_to or (v_to - v_from) > 730 then
        raise exception 'El período de consulta no es válido.'
            using errcode = '22023';
    end if;

    with sales as (
        select
            s.*,
            (s.sold_at at time zone 'America/Bogota')::date as sold_date,
            coalesce(a.actor_email, 'Sistema') as actor_email,
            coalesce(a.actor_role, 'system') as actor_role
        from public.store_sales s
        left join lateral (
            select al.actor_email, al.actor_role
            from public.audit_logs al
            where al.gym_id = s.gym_id
              and al.entity_type = 'store_sales'
              and al.entity_id = s.id::text
              and al.action in ('VENTA_TIENDA', 'VENTA_EDITADA')
            order by al.id desc
            limit 1
        ) a on true
        where s.gym_id = p_gym_id
          and coalesce(s.sale_status, 'posted') = 'posted'
          and (s.sold_at at time zone 'America/Bogota')::date
              between v_from and v_to
    )
    select jsonb_build_object(
        'date_from', v_from,
        'date_to', v_to,
        'store_income', coalesce((select sum(total_amount) from sales), 0),
        'sale_count', (select count(*) from sales),
        'average_sale', coalesce((
            select round(avg(total_amount))::bigint from sales
        ), 0),
        'by_product', coalesce((
            select jsonb_agg(
                jsonb_build_object(
                    'label', grouped.product_name,
                    'count', grouped.units_sold,
                    'transactions', grouped.sale_count,
                    'total', grouped.total
                ) order by grouped.total desc, grouped.product_name
            )
            from (
                select product_name,
                    sum(quantity)::bigint as units_sold,
                    count(*) as sale_count,
                    sum(total_amount)::bigint as total
                from sales
                group by product_name
            ) grouped
        ), '[]'::jsonb),
        'by_method', coalesce((
            select jsonb_agg(
                jsonb_build_object(
                    'label', grouped.payment_method,
                    'count', grouped.sale_count,
                    'total', grouped.total
                ) order by grouped.total desc, grouped.payment_method
            )
            from (
                select payment_method,
                    count(*) as sale_count,
                    sum(total_amount)::bigint as total
                from sales
                group by payment_method
            ) grouped
        ), '[]'::jsonb),
        'sales', coalesce((
            select jsonb_agg(
                jsonb_build_object(
                    'id', item.id,
                    'product_id', item.product_id,
                    'product_name', item.product_name,
                    'product_sku', item.product_sku,
                    'quantity', item.quantity,
                    'unit_price', item.unit_price,
                    'total_amount', item.total_amount,
                    'payment_method', item.payment_method,
                    'payment_reference', item.payment_reference,
                    'customer_name', item.customer_name,
                    'notes', item.notes,
                    'sold_by', item.sold_by,
                    'sold_at', item.sold_at,
                    'sale_status', item.sale_status,
                    'sale_revision', item.sale_revision,
                    'sale_changed_at', item.sale_changed_at,
                    'sale_change_reason', item.sale_change_reason,
                    'actor_email', item.actor_email,
                    'actor_role', item.actor_role
                ) order by item.sold_at desc, item.id desc
            ) from sales item
        ), '[]'::jsonb)
    ) into result;

    return result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_gym(p_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    new_gym_id uuid;
begin
    if auth.uid() is null then
        raise exception 'Debes iniciar sesión.';
    end if;

    insert into public.gyms(
        name,
        created_by
    )
    values (
        trim(p_name),
        auth.uid()
    )
    returning id into new_gym_id;

    insert into public.gym_users(
        gym_id,
        user_id,
        role
    )
    values (
        new_gym_id,
        auth.uid(),
        'admin'
    );

    insert into public.plans(
        gym_id,
        name,
        duration_days,
        price,
        entry_limit,
        active
    )
    values
        (
            new_gym_id,
            'Mensual',
            30,
            55000,
            null,
            true
        ),
        (
            new_gym_id,
            'Semanal',
            7,
            25000,
            null,
            true
        ),
        (
            new_gym_id,
            'Tiquetera',
            30,
            50000,
            30,
            true
        );

    return new_gym_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_reception_invite()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_gym_id uuid;
    v_code uuid;
begin
    select gu.gym_id
    into v_gym_id
    from public.gym_users gu
    where gu.user_id = (select auth.uid())
      and gu.role = 'admin'
    order by gu.gym_id
    limit 1;

    if v_gym_id is null then
        raise exception 'Solo un administrador puede crear invitaciones.'
            using errcode = '42501';
    end if;

    update public.staff_invites
    set expires_at = now()
    where gym_id = v_gym_id
      and used_at is null
      and expires_at > now();

    insert into public.staff_invites(
        gym_id,
        role,
        created_by,
        expires_at
    )
    values (
        v_gym_id,
        'receptionist',
        (select auth.uid()),
        now() + interval '6 months'
    )
    returning code into v_code;

    return v_code;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_attendance_statistics(p_gym_id uuid, p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    if not private.user_has_gym_role(
        p_gym_id,
        array['admin']::text[]
    ) then
        raise exception 'Las estadísticas son exclusivas del administrador.'
            using errcode = '42501';
    end if;

    return public.get_attendance_statistics_internal(
        p_gym_id,
        p_days
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_attendance_statistics_internal(p_gym_id uuid, p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
    v_today date := public.ztattuz_today();
    v_days integer := least(
        greatest(coalesce(p_days, 30), 7),
        90
    );
    v_result jsonb;
begin
    with bounds as (
        select
            v_today as today_date,
            v_today - (v_days - 1) as period_start,
            v_today - ((v_days * 2) - 1) as previous_start,
            v_today - v_days as previous_end,
            date_trunc(
                'week',
                v_today::timestamp
            )::date as week_start,
            date_trunc(
                'month',
                v_today::timestamp
            )::date as month_start,
            v_today - (least(v_days, 30) - 1) as chart_start,
            least(
                v_today - ((v_days * 2) - 1),
                v_today - 29,
                date_trunc(
                    'week',
                    v_today::timestamp
                )::date,
                date_trunc(
                    'month',
                    v_today::timestamp
                )::date
            ) as fetch_start
    ),
    raw_checkins as (
        select
            c.id,
            c.client_id,
            c.membership_id,
            c.checkin_at at time zone 'America/Bogota'
                as local_at,
            cl.document,
            trim(
                concat_ws(
                    ' ',
                    cl.first_name,
                    cl.last_name
                )
            ) as client_name,
            coalesce(p.name, 'Sin plan') as plan_name,
            coalesce(
                m.entry_limit,
                p.entry_limit
            ) as entry_limit
        from public.checkins c
        join public.clients cl
          on cl.id = c.client_id
         and cl.gym_id = c.gym_id
        left join public.memberships m
          on m.id = c.membership_id
         and m.gym_id = c.gym_id
        left join public.plans p
          on p.id = m.plan_id
         and p.gym_id = c.gym_id
        cross join bounds b
        where c.gym_id = p_gym_id
          and c.result = 'PERMITIDA'
          and c.checkin_at >= (
              b.fetch_start::timestamp
              at time zone 'America/Bogota'
          )
          and c.checkin_at < (
              (b.today_date + 1)::timestamp
              at time zone 'America/Bogota'
          )
    ),
    classified as (
        select
            r.*,
            r.local_at::date as local_day,
            case
                when lower(r.plan_name) like '%tiquet%'
                     or coalesce(r.entry_limit, 0) > 1
                    then 'Tiquetera'
                when coalesce(r.entry_limit, 0) = 1
                     or lower(r.plan_name) ~
                        '(sesion|sesión|diario|día|dia|visita)'
                    then 'Sesión'
                when r.plan_name = 'Sin plan'
                    then 'Sin plan'
                else 'Mensualidad'
            end as plan_type
        from raw_checkins r
    ),
    period_rows as (
        select c.*
        from classified c
        cross join bounds b
        where c.local_day between
            b.period_start and b.today_date
    ),
    previous_rows as (
        select c.*
        from classified c
        cross join bounds b
        where c.local_day between
            b.previous_start and b.previous_end
    ),
    metric_values as (
        select
            count(*) filter (
                where c.local_day = b.today_date
            ) as today_entries,
            count(distinct c.client_id) filter (
                where c.local_day = b.today_date
            ) as today_unique,
            count(*) filter (
                where c.local_day between
                    b.week_start and b.today_date
            ) as week_entries,
            count(distinct c.client_id) filter (
                where c.local_day between
                    b.week_start and b.today_date
            ) as week_unique,
            count(*) filter (
                where c.local_day between
                    b.month_start and b.today_date
            ) as month_entries,
            count(distinct c.client_id) filter (
                where c.local_day between
                    b.month_start and b.today_date
            ) as month_unique,
            (
                select count(*)
                from period_rows
            ) as period_entries,
            (
                select count(distinct client_id)
                from period_rows
            ) as period_unique,
            (
                select count(*)
                from previous_rows
            ) as previous_entries
        from bounds b
        left join classified c on true
        group by
            b.today_date,
            b.week_start,
            b.month_start
    ),
    plan_types(sort_order, plan_type) as (
        values
            (1, 'Sesión'),
            (2, 'Mensualidad'),
            (3, 'Tiquetera'),
            (4, 'Sin plan')
    ),
    plan_counts as (
        select
            p.plan_type,
            count(*) as entries,
            count(distinct p.client_id) as people
        from period_rows p
        group by p.plan_type
    ),
    plan_json as (
        select coalesce(
            jsonb_agg(
                jsonb_build_object(
                    'type', t.plan_type,
                    'people', coalesce(c.people, 0),
                    'entries', coalesce(c.entries, 0),
                    'percentage', case
                        when m.period_entries = 0 then 0
                        else round(
                            coalesce(c.entries, 0)::numeric
                            * 100
                            / m.period_entries,
                            1
                        )
                    end
                )
                order by t.sort_order
            ),
            '[]'::jsonb
        ) as value
        from plan_types t
        left join plan_counts c
          on c.plan_type = t.plan_type
        cross join metric_values m
    ),
    daily_days as (
        select generate_series(
            b.chart_start::timestamp,
            b.today_date::timestamp,
            interval '1 day'
        )::date as day
        from bounds b
    ),
    daily_counts as (
        select
            c.local_day as day,
            count(*) as entries
        from classified c
        cross join bounds b
        where c.local_day between
            b.chart_start and b.today_date
        group by c.local_day
    ),
    daily_json as (
        select coalesce(
            jsonb_agg(
                jsonb_build_object(
                    'date', d.day,
                    'count', coalesce(c.entries, 0)
                )
                order by d.day
            ),
            '[]'::jsonb
        ) as value
        from daily_days d
        left join daily_counts c
          on c.day = d.day
    ),
    weekday_counts as (
        select
            extract(isodow from p.local_at)::integer
                as weekday_number,
            case extract(isodow from p.local_at)::integer
                when 1 then 'Lunes'
                when 2 then 'Martes'
                when 3 then 'Miércoles'
                when 4 then 'Jueves'
                when 5 then 'Viernes'
                when 6 then 'Sábado'
                else 'Domingo'
            end as weekday_name,
            count(*) as entries
        from period_rows p
        group by extract(isodow from p.local_at)
    ),
    peak_hours as (
        select
            extract(hour from p.local_at)::integer as hour_number,
            count(*) as entries
        from period_rows p
        group by extract(hour from p.local_at)
    ),
    active_clients as (
        select c.id
        from public.clients c
        where c.gym_id = p_gym_id
          and c.active = true
    ),
    recent_visits as (
        select
            c.client_id,
            max(c.local_day) as last_visit
        from classified c
        cross join bounds b
        where c.local_day between
            b.today_date - 29 and b.today_date
        group by c.client_id
    ),
    inactivity_values as (
        select
            count(a.id) as active_clients,
            count(a.id) filter (
                where r.last_visit is null
                   or r.last_visit < v_today - 6
            ) as inactive_7,
            count(a.id) filter (
                where r.last_visit is null
                   or r.last_visit < v_today - 14
            ) as inactive_15,
            count(a.id) filter (
                where r.last_visit is null
                   or r.last_visit < v_today - 29
            ) as inactive_30
        from active_clients a
        left join recent_visits r
          on r.client_id = a.id
    ),
    top_rows as (
        select
            p.client_id,
            max(p.document) as document,
            max(p.client_name) as client_name,
            count(*) as entries,
            max(p.local_day) as last_visit,
            (
                array_agg(
                    p.plan_type
                    order by p.local_at desc
                )
            )[1] as plan_type
        from period_rows p
        group by p.client_id
        order by count(*) desc, max(p.client_name)
        limit 10
    ),
    top_json as (
        select coalesce(
            jsonb_agg(
                jsonb_build_object(
                    'client_id', t.client_id,
                    'document', t.document,
                    'client_name', t.client_name,
                    'plan_type', t.plan_type,
                    'entries', t.entries,
                    'last_visit', t.last_visit
                )
                order by t.entries desc, t.client_name
            ),
            '[]'::jsonb
        ) as value
        from top_rows t
    )
    select jsonb_build_object(
        'days', v_days,
        'generated_at', now(),
        'metrics', jsonb_build_object(
            'today_entries', m.today_entries,
            'today_unique', m.today_unique,
            'week_entries', m.week_entries,
            'week_unique', m.week_unique,
            'month_entries', m.month_entries,
            'month_unique', m.month_unique,
            'period_entries', m.period_entries,
            'period_unique', m.period_unique,
            'previous_entries', m.previous_entries,
            'daily_average', round(
                m.period_entries::numeric / v_days,
                1
            ),
            'trend_percentage', case
                when m.previous_entries = 0 then
                    case
                        when m.period_entries = 0 then 0
                        else 100
                    end
                else round(
                    (
                        m.period_entries
                        - m.previous_entries
                    )::numeric
                    * 100
                    / m.previous_entries,
                    1
                )
            end,
            'busiest_weekday', coalesce(
                (
                    select w.weekday_name
                    from weekday_counts w
                    order by
                        w.entries desc,
                        w.weekday_number
                    limit 1
                ),
                'Sin datos'
            ),
            'peak_hour', coalesce(
                (
                    select
                        lpad(h.hour_number::text, 2, '0')
                        || ':00 – '
                        || lpad(h.hour_number::text, 2, '0')
                        || ':59'
                    from peak_hours h
                    order by
                        h.entries desc,
                        h.hour_number
                    limit 1
                ),
                'Sin datos'
            ),
            'active_clients', i.active_clients,
            'inactive_7', i.inactive_7,
            'inactive_15', i.inactive_15,
            'inactive_30', i.inactive_30
        ),
        'plan_breakdown', p.value,
        'daily_series', d.value,
        'top_clients', t.value
    )
    into v_result
    from metric_values m
    cross join inactivity_values i
    cross join plan_json p
    cross join daily_json d
    cross join top_json t;

    return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_audit_logs(p_gym_id uuid, p_limit integer DEFAULT 200, p_action text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_result jsonb;
begin
    if not private.user_has_gym_role(
        p_gym_id,
        array['admin']::text[]
    ) then
        raise exception 'La auditoría es exclusiva del administrador.'
            using errcode = '42501';
    end if;

    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id', recent.id,
                'actor_user_id', recent.actor_user_id,
                'actor_email', recent.actor_email,
                'actor_role', recent.actor_role,
                'action', recent.action,
                'entity_type', recent.entity_type,
                'entity_id', recent.entity_id,
                'summary', recent.summary,
                'details', recent.details,
                'created_at', recent.created_at
            )
            order by recent.created_at desc, recent.id desc
        ),
        '[]'::jsonb
    )
    into v_result
    from (
        select al.*
        from public.audit_logs al
        where al.gym_id = p_gym_id
          and (
              trim(coalesce(p_action, '')) = ''
              or al.action = trim(p_action)
          )
        order by al.created_at desc, al.id desc
        limit least(greatest(coalesce(p_limit, 200), 1), 500)
    ) recent;

    return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_finance_dashboard(p_gym_id uuid, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_from date := coalesce(
        p_date_from,
        date_trunc('month', public.ztattuz_today())::date
    );
    v_to date := coalesce(p_date_to, public.ztattuz_today());
    v_result jsonb;
begin
    if not private.user_has_gym_role(
        p_gym_id,
        array['admin']::text[]
    ) then
        raise exception 'Las finanzas son exclusivas del administrador.'
            using errcode = '42501';
    end if;

    if v_from > v_to then
        raise exception 'La fecha inicial no puede superar la fecha final.'
            using errcode = '22023';
    end if;

    if (v_to - v_from) > 730 then
        raise exception 'El período máximo permitido es de 730 días.'
            using errcode = '22023';
    end if;

    with payments as (
        select
            m.id,
            m.client_id,
            trim(concat_ws(' ', c.first_name, c.last_name))
                as client_name,
            c.document,
            coalesce(p.name, 'Sin plan') as plan_name,
            coalesce(m.amount, m.amount_paid, 0)::bigint as amount,
            coalesce(m.payment_method, 'SIN DEFINIR') as payment_method,
            coalesce(m.payment_reference, '') as payment_reference,
            m.start_date,
            m.end_date,
            m.paid_at,
            m.recorded_by,
            coalesce(
                nullif(a.actor_email, ''),
                case
                    when m.recorded_by is null then 'Anterior al registro'
                    else 'Usuario ' || left(m.recorded_by::text, 8)
                end
            ) as actor_email,
            coalesce(
                nullif(a.actor_role, ''),
                case
                    when m.recorded_by is null then 'system'
                    else 'authenticated'
                end
            ) as actor_role,
            (m.paid_at at time zone 'America/Bogota')::date as paid_date
        from public.memberships m
        join public.clients c
          on c.id = m.client_id
         and c.gym_id = m.gym_id
        left join public.plans p
          on p.id = m.plan_id
         and p.gym_id = m.gym_id
        left join lateral (
            select
                al.actor_email,
                al.actor_role
            from public.audit_logs al
            where al.gym_id = m.gym_id
              and al.entity_type = 'memberships'
              and al.entity_id = m.id::text
              and al.action = 'PAGO_REGISTRADO'
            order by al.created_at asc, al.id asc
            limit 1
        ) a on true
        where m.gym_id = p_gym_id AND m.payment_status = 'posted' /* ZTATTUZ_PAYMENT_VOID_FILTER_V1 */
          and (m.paid_at at time zone 'America/Bogota')::date
              between v_from and v_to
    )
    select jsonb_build_object(
        'date_from', v_from,
        'date_to', v_to,
        'total_income', coalesce((
            select sum(amount) from payments
        ), 0),
        'payment_count', (
            select count(*) from payments
        ),
        'average_payment', coalesce((
            select round(avg(amount))::bigint from payments
        ), 0),
        'by_method', coalesce((
            select jsonb_agg(
                jsonb_build_object(
                    'label', grouped.payment_method,
                    'count', grouped.payment_count,
                    'total', grouped.total
                )
                order by grouped.total desc, grouped.payment_method
            )
            from (
                select
                    payment_method,
                    count(*) as payment_count,
                    sum(amount)::bigint as total
                from payments
                group by payment_method
            ) grouped
        ), '[]'::jsonb),
        'by_plan', coalesce((
            select jsonb_agg(
                jsonb_build_object(
                    'label', grouped.plan_name,
                    'count', grouped.payment_count,
                    'total', grouped.total
                )
                order by grouped.total desc, grouped.plan_name
            )
            from (
                select
                    plan_name,
                    count(*) as payment_count,
                    sum(amount)::bigint as total
                from payments
                group by plan_name
            ) grouped
        ), '[]'::jsonb),
        'by_day', coalesce((
            select jsonb_agg(
                jsonb_build_object(
                    'date', grouped.paid_date,
                    'count', grouped.payment_count,
                    'total', grouped.total
                )
                order by grouped.paid_date
            )
            from (
                select
                    paid_date,
                    count(*) as payment_count,
                    sum(amount)::bigint as total
                from payments
                group by paid_date
            ) grouped
        ), '[]'::jsonb),
        'payments', coalesce((
            select jsonb_agg(
                jsonb_build_object(
                    'id', item.id,
                    'client_id', item.client_id,
                    'client_name', item.client_name,
                    'document', item.document,
                    'plan_name', item.plan_name,
                    'amount', item.amount,
                    'payment_method', item.payment_method,
                    'payment_reference', item.payment_reference,
                    'start_date', item.start_date,
                    'end_date', item.end_date,
                    'paid_at', item.paid_at,
                    'actor_email', item.actor_email,
                    'actor_role', item.actor_role
                )
                order by item.paid_at desc, item.id desc
            )
            from payments item
        ), '[]'::jsonb)
    )
    into v_result;

    return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.is_gym_member(target_gym uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select exists (
        select 1
        from public.gym_users
        where gym_id = target_gym
          and user_id = auth.uid()
    );
$function$
;

CREATE OR REPLACE FUNCTION public.join_gym(p_join_code uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    selected_gym uuid;
begin
    if auth.uid() is null then
        raise exception 'Debes iniciar sesión.';
    end if;

    select id
    into selected_gym
    from public.gyms
    where join_code = p_join_code;

    if selected_gym is null then
        raise exception 'Código de gimnasio incorrecto.';
    end if;

    insert into public.gym_users(gym_id, user_id, role)
    values (selected_gym, auth.uid(), 'admin')
    on conflict do nothing;

    return selected_gym;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.reception_account_context()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_result jsonb;
begin
    select jsonb_build_object(
        'gym_id', gu.gym_id,
        'gym_name', g.name,
        'role', gu.role
    )
    into v_result
    from public.gym_users gu
    join public.gyms g
      on g.id = gu.gym_id
    where gu.user_id = (select auth.uid())
      and gu.role in ('admin', 'receptionist')
    order by gu.gym_id
    limit 1;

    if v_result is null then
        raise exception 'Esta cuenta todavía no pertenece a un gimnasio.'
            using errcode = 'P0002';
    end if;

    return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.reception_create_expense(p_gym_id uuid, p_expense_date date, p_category text, p_description text, p_vendor text, p_amount bigint, p_payment_method text, p_payment_reference text, p_receipt_reference text, p_notes text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_id bigint;
    v_category text := btrim(coalesce(p_category, ''));
    v_description text := btrim(coalesce(p_description, ''));
    v_vendor text := btrim(coalesce(p_vendor, ''));
    v_method text := btrim(coalesce(p_payment_method, ''));
    v_payment_reference text := btrim(coalesce(p_payment_reference, ''));
    v_receipt_reference text := btrim(coalesce(p_receipt_reference, ''));
    v_notes text := btrim(coalesce(p_notes, ''));
begin
    if p_gym_id is null
       or not private.user_has_gym_role(
           p_gym_id,
           array['admin', 'receptionist']::text[]
       ) then
        raise exception 'Esta cuenta no puede registrar gastos.'
            using errcode = '42501';
    end if;

    if p_expense_date is null then
        raise exception 'La fecha del gasto es obligatoria.'
            using errcode = '22023';
    end if;

    if v_category = '' or length(v_category) > 80 then
        raise exception 'La categoría del gasto no es válida.'
            using errcode = '22023';
    end if;

    if v_description = '' or length(v_description) > 240 then
        raise exception 'El concepto del gasto es obligatorio y debe ser corto.'
            using errcode = '22023';
    end if;

    if length(v_vendor) > 160
       or length(v_method) > 40
       or length(v_payment_reference) > 120
       or length(v_receipt_reference) > 120
       or length(v_notes) > 500 then
        raise exception 'Uno de los datos del gasto supera el límite permitido.'
            using errcode = '22023';
    end if;

    if p_amount is null or p_amount <= 0 or p_amount > 1000000000000000 then
        raise exception 'El valor del gasto debe ser mayor que cero.'
            using errcode = '22023';
    end if;

    if v_method = '' then
        v_method := 'Efectivo';
    end if;

    insert into public.accounting_expenses(
        gym_id,
        expense_date,
        category,
        description,
        vendor,
        amount,
        payment_method,
        payment_reference,
        receipt_reference,
        notes,
        recorded_by
    )
    values (
        p_gym_id,
        p_expense_date,
        v_category,
        v_description,
        v_vendor,
        p_amount,
        v_method,
        v_payment_reference,
        v_receipt_reference,
        v_notes,
        (select auth.uid())
    )
    returning id into v_id;

    return v_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.reception_find_client_by_biometric(p_gym_id uuid, p_biometric_identifier text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_result jsonb;
    v_code text := upper(regexp_replace(
        coalesce(p_biometric_identifier, ''),
        '[[:space:]]+',
        '',
        'g'
    ));
begin
    if not private.user_has_gym_role(
        p_gym_id,
        array['admin', 'receptionist']::text[]
    ) then
        raise exception 'No tienes permiso para validar ingresos.'
            using errcode = '42501';
    end if;

    if v_code = '' then
        return null;
    end if;

    select private.membership_snapshot_json(p_gym_id, c.id)
    into v_result
    from public.clients c
    where c.gym_id = p_gym_id
      and upper(trim(c.biometric_identifier)) = v_code
      and coalesce(c.active, true)
    limit 1;

    return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.reception_list_checkins(p_gym_id uuid, p_limit integer DEFAULT 40)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_result jsonb;
begin
    if not private.user_has_gym_role(
        p_gym_id,
        array['admin', 'receptionist']::text[]
    ) then
        raise exception 'No tienes permiso para consultar entradas.'
            using errcode = '42501';
    end if;

    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id', recent.id,
                'client_id', recent.client_id,
                'document', recent.document,
                'client_name', recent.client_name,
                'checkin_at', recent.checkin_at,
                'method', recent.method,
                'result', recent.result
            )
            order by recent.checkin_at desc, recent.id desc
        ),
        '[]'::jsonb
    )
    into v_result
    from (
        select
            ch.id,
            ch.client_id,
            c.document,
            trim(concat_ws(' ', c.first_name, c.last_name))
                as client_name,
            ch.checkin_at,
            ch.method,
            ch.result
        from public.checkins ch
        join public.clients c
          on c.id = ch.client_id
         and c.gym_id = ch.gym_id
        where ch.gym_id = p_gym_id
        order by ch.checkin_at desc, ch.id desc
        limit least(greatest(coalesce(p_limit, 40), 1), 100)
    ) recent;

    return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.reception_list_clients(p_gym_id uuid, p_search text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_result jsonb;
begin
    if not private.user_has_gym_role(
        p_gym_id,
        array['admin', 'receptionist']::text[]
    ) then
        raise exception 'No tienes permiso para ver estos clientes.'
            using errcode = '42501';
    end if;

    select coalesce(
        jsonb_agg(
            private.membership_snapshot_json(p_gym_id, c.id)
            || jsonb_build_object(
                'biometric_identifier',
                coalesce(c.biometric_identifier, '')
            )
            order by c.first_name, c.last_name, c.id
        ),
        '[]'::jsonb
    )
    into v_result
    from public.clients c
    where c.gym_id = p_gym_id
      and (
          trim(coalesce(p_search, '')) = ''
          or c.document ilike '%' || trim(p_search) || '%'
          or concat_ws(' ', c.first_name, c.last_name)
              ilike '%' || trim(p_search) || '%'
          or coalesce(c.phone, '') ilike '%' || trim(p_search) || '%'
          or coalesce(c.email, '') ilike '%' || trim(p_search) || '%'
          or coalesce(c.biometric_identifier, '')
              ilike '%' || trim(p_search) || '%'
      );

    return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.reception_list_memberships(p_gym_id uuid, p_client_id bigint, p_limit integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_result jsonb;
begin
    if not private.user_has_gym_role(
        p_gym_id,
        array['admin', 'receptionist']::text[]
    ) then
        raise exception 'No tienes permiso para consultar pagos.'
            using errcode = '42501';
    end if;

    if not private.client_belongs_to_gym(
        p_client_id,
        p_gym_id
    ) then
        raise exception 'Cliente no encontrado.' using errcode = 'P0002';
    end if;

    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id', recent.id,
                'plan_id', recent.plan_id,
                'plan_name', recent.plan_name,
                'start_date', recent.start_date,
                'end_date', recent.end_date,
                'amount', recent.amount,
                'payment_method', recent.payment_method,
                'payment_reference', recent.payment_reference,
                'paid_at', recent.paid_at,
                'notes', recent.notes
            )
            order by recent.paid_at desc, recent.id desc
        ),
        '[]'::jsonb
    )
    into v_result
    from (
        select
            m.id,
            m.plan_id,
            coalesce(p.name, 'Sin plan') as plan_name,
            m.start_date,
            m.end_date,
            coalesce(m.amount, m.amount_paid, 0)::bigint as amount,
            coalesce(m.payment_method, '') as payment_method,
            coalesce(m.payment_reference, '') as payment_reference,
            m.paid_at,
            coalesce(m.notes, '') as notes
        from public.memberships m
        left join public.plans p
          on p.id = m.plan_id
         and p.gym_id = m.gym_id
        where m.gym_id = p_gym_id AND m.payment_status = 'posted' /* ZTATTUZ_PAYMENT_VOID_FILTER_V1 */
          and m.client_id = p_client_id
        order by m.paid_at desc, m.id desc
        limit least(greatest(coalesce(p_limit, 30), 1), 100)
    ) recent;

    return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.reception_list_store_products(p_gym_id uuid, p_search text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_search text := trim(coalesce(p_search, ''));
    v_result jsonb;
begin
    if not private.user_has_gym_role(
        p_gym_id,
        array['admin', 'receptionist']::text[]
    ) then
        raise exception 'No tienes permiso para consultar la tienda.'
            using errcode = '42501';
    end if;

    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'id', p.id,
                'name', p.name,
                'sku', p.sku,
                'sale_price', p.sale_price,
                'stock_quantity', p.stock_quantity,
                'low_stock_threshold', p.low_stock_threshold,
                'image_data', coalesce(p.image_data, ''),
                'available', p.stock_quantity > 0
            )
            order by (p.stock_quantity > 0) desc, p.name
        ),
        '[]'::jsonb
    )
    into v_result
    from public.store_products p
    where p.gym_id = p_gym_id
      and p.active = true
      and (
          v_search = ''
          or p.name ilike '%' || v_search || '%'
          or p.sku ilike '%' || v_search || '%'
      );

    return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.reception_membership_snapshot(p_gym_id uuid, p_client_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    if not private.user_has_gym_role(
        p_gym_id,
        array['admin', 'receptionist']::text[]
    ) then
        raise exception 'No tienes permiso para consultar este cliente.'
            using errcode = '42501';
    end if;

    return private.membership_snapshot_json(
        p_gym_id,
        p_client_id
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.reception_register_checkin(p_gym_id uuid, p_client_id bigint, p_method text DEFAULT 'RECEPCIÓN'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_snapshot jsonb;
    v_membership_id bigint;
    v_allowed boolean;
    v_result text;
    v_checkin_at timestamptz := public.ztattuz_now();
begin
    if not private.user_has_gym_role(
        p_gym_id,
        array['admin', 'receptionist']::text[]
    ) then
        raise exception 'No tienes permiso para registrar entradas.'
            using errcode = '42501';
    end if;

    v_snapshot := private.membership_snapshot_json(
        p_gym_id,
        p_client_id
    );
    v_membership_id := nullif(
        v_snapshot ->> 'membership_id',
        ''
    )::bigint;

    if v_membership_id is not null then
        perform 1
        from public.memberships m
        where m.id = v_membership_id
          and m.gym_id = p_gym_id
        for update;

        v_snapshot := private.membership_snapshot_json(
            p_gym_id,
            p_client_id
        );
    end if;

    v_allowed := coalesce(
        (v_snapshot ->> 'allowed')::boolean,
        false
    );
    v_result := case
        when v_allowed then 'PERMITIDA'
        else 'DENEGADA'
    end;

    insert into public.checkins(
        gym_id,
        client_id,
        membership_id,
        checkin_at,
        method,
        result,
        notes,
        recorded_by
    )
    values (
        p_gym_id,
        p_client_id,
        v_membership_id,
        v_checkin_at,
        left(trim(coalesce(p_method, 'RECEPCIÓN')), 80),
        v_result,
        '',
        (select auth.uid())
    );

    if v_allowed
       and (v_snapshot ->> 'entry_limit') is not null then
        v_snapshot := jsonb_set(
            v_snapshot,
            '{entries_used}',
            to_jsonb((v_snapshot ->> 'entries_used')::bigint + 1)
        );
        v_snapshot := jsonb_set(
            v_snapshot,
            '{entries_remaining}',
            to_jsonb(
                greatest(
                    (v_snapshot ->> 'entries_remaining')::bigint - 1,
                    0
                )
            )
        );
    end if;

    return v_snapshot || jsonb_build_object(
        'result', v_result,
        'checkin_at', v_checkin_at,
        'override', false
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.reception_save_client(p_gym_id uuid, p_client_id bigint, p_document text, p_first_name text, p_last_name text, p_phone text DEFAULT ''::text, p_email text DEFAULT ''::text, p_birthdate date DEFAULT NULL::date, p_biometric_identifier text DEFAULT ''::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_client_id bigint;
    v_user_id uuid := (select auth.uid());
    v_biometric_identifier text := nullif(
        upper(regexp_replace(
            coalesce(p_biometric_identifier, ''),
            '[[:space:]]+',
            '',
            'g'
        )),
        ''
    );
begin
    if not private.user_has_gym_role(
        p_gym_id,
        array['admin', 'receptionist']::text[]
    ) then
        raise exception 'No tienes permiso para guardar clientes.'
            using errcode = '42501';
    end if;

    if trim(coalesce(p_document, '')) = ''
       or trim(coalesce(p_first_name, '')) = '' then
        raise exception 'El documento y el nombre son obligatorios.'
            using errcode = '22023';
    end if;

    if v_biometric_identifier is not null and exists (
        select 1
        from public.clients c
        where c.gym_id = p_gym_id
          and upper(trim(c.biometric_identifier)) = v_biometric_identifier
          and (p_client_id is null or c.id <> p_client_id)
    ) then
        raise exception 'Este identificador biométrico ya pertenece a otro cliente.'
            using errcode = '23505';
    end if;

    if p_client_id is null then
        insert into public.clients(
            gym_id,
            document,
            full_name,
            first_name,
            last_name,
            phone,
            email,
            birth_date,
            birthdate,
            emergency_contact,
            medical_notes,
            biometric_identifier,
            photo_path,
            active,
            created_by
        )
        values (
            p_gym_id,
            trim(p_document),
            trim(concat_ws(' ', p_first_name, p_last_name)),
            trim(p_first_name),
            trim(coalesce(p_last_name, '')),
            trim(coalesce(p_phone, '')),
            trim(coalesce(p_email, '')),
            p_birthdate,
            p_birthdate,
            '',
            '',
            v_biometric_identifier,
            '',
            true,
            v_user_id
        )
        returning id into v_client_id;
    else
        if not private.client_belongs_to_gym(
            p_client_id,
            p_gym_id
        ) then
            raise exception 'Cliente no encontrado.' using errcode = 'P0002';
        end if;

        update public.clients
        set
            document = trim(p_document),
            full_name = trim(concat_ws(' ', p_first_name, p_last_name)),
            first_name = trim(p_first_name),
            last_name = trim(coalesce(p_last_name, '')),
            phone = trim(coalesce(p_phone, '')),
            email = trim(coalesce(p_email, '')),
            birth_date = p_birthdate,
            birthdate = p_birthdate,
            biometric_identifier = v_biometric_identifier
        where id = p_client_id
          and gym_id = p_gym_id
        returning id into v_client_id;
    end if;

    return v_client_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.redeem_reception_invite(p_code uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_invite record;
    v_user_id uuid := (select auth.uid());
begin
    if v_user_id is null then
        raise exception 'Debes iniciar sesión.' using errcode = '42501';
    end if;

    if exists (
        select 1
        from public.gym_users gu
        where gu.user_id = v_user_id
    ) then
        raise exception 'Esta cuenta ya pertenece a un gimnasio.'
            using errcode = '23505';
    end if;

    select si.*
    into v_invite
    from public.staff_invites si
    where si.code = p_code
      and si.role = 'receptionist'
      and si.used_at is null
      and si.expires_at > now()
    for update;

    if not found then
        raise exception 'La invitación no existe o ya venció.'
            using errcode = '22023';
    end if;

    insert into public.gym_users(
        gym_id,
        user_id,
        role
    )
    values (
        v_invite.gym_id,
        v_user_id,
        'receptionist'
    );

    update public.staff_invites
    set
        used_by = v_user_id,
        used_at = now()
    where id = v_invite.id;

    return v_invite.gym_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.register_store_sale(p_gym_id uuid, p_product_id bigint, p_quantity integer, p_payment_method text, p_payment_reference text, p_customer_name text, p_notes text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_product record;
    v_sale_id bigint;
    v_sold_at timestamptz;
    v_total bigint;
    v_remaining integer;
    v_payment_method text := upper(
        coalesce(nullif(trim(p_payment_method), ''), 'EFECTIVO')
    );
    v_user_id uuid := (select auth.uid());
begin
    if not private.user_has_gym_role(
        p_gym_id,
        array['admin', 'receptionist']::text[]
    ) then
        raise exception 'No tienes permiso para registrar ventas.'
            using errcode = '42501';
    end if;

    if coalesce(p_quantity, 0) <= 0 then
        raise exception 'La cantidad debe ser mayor que cero.'
            using errcode = '22023';
    end if;

    if v_payment_method not in (
        'EFECTIVO',
        'TRANSFERENCIA',
        'TARJETA',
        'OTRO'
    ) then
        raise exception 'El método de pago no es válido.'
            using errcode = '22023';
    end if;

    select p.*
    into v_product
    from public.store_products p
    where p.id = p_product_id
      and p.gym_id = p_gym_id
    for update;

    if not found or not coalesce(v_product.active, false) then
        raise exception 'El producto no existe o está desactivado.'
            using errcode = 'P0002';
    end if;

    if v_product.stock_quantity < p_quantity then
        raise exception 'Existencias insuficientes. Disponibles: %.',
            v_product.stock_quantity
            using errcode = '22023';
    end if;

    v_total := v_product.sale_price * p_quantity;
    v_remaining := v_product.stock_quantity - p_quantity;

    update public.store_products
    set
        stock_quantity = v_remaining,
        updated_by = v_user_id,
        updated_at = now()
    where id = v_product.id
      and gym_id = p_gym_id;

    insert into public.store_sales(
        gym_id,
        product_id,
        product_name,
        product_sku,
        quantity,
        unit_price,
        total_amount,
        payment_method,
        payment_reference,
        customer_name,
        notes,
        sold_by
    )
    values (
        p_gym_id,
        v_product.id,
        v_product.name,
        v_product.sku,
        p_quantity,
        v_product.sale_price,
        v_total,
        v_payment_method,
        trim(coalesce(p_payment_reference, '')),
        trim(coalesce(p_customer_name, '')),
        trim(coalesce(p_notes, '')),
        v_user_id
    )
    returning id, sold_at into v_sale_id, v_sold_at;

    return jsonb_build_object(
        'sale_id', v_sale_id,
        'product_id', v_product.id,
        'product_name', v_product.name,
        'quantity', p_quantity,
        'unit_price', v_product.sale_price,
        'total_amount', v_total,
        'stock_remaining', v_remaining,
        'sold_at', v_sold_at
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ztattuz_change_payment(p_gym_id uuid, p_membership_id bigint, p_expected_revision bigint, p_action text, p_reason text, p_amount bigint DEFAULT NULL::bigint, p_payment_method text DEFAULT NULL::text, p_payment_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    payment public.memberships%rowtype;
    client_key bigint;
begin
    if not private.user_has_gym_role(p_gym_id, array['admin','receptionist']::text[]) then
        raise exception 'No tienes permiso para modificar pagos de este gimnasio.' using errcode='42501';
    end if;
    if p_action is null or p_action not in ('correct', 'void') then
        raise exception 'Acción no válida.' using errcode='22023';
    end if;
    if length(trim(coalesce(p_reason, ''))) not between 3 and 500 then
        raise exception 'Escribe un motivo de 3 a 500 caracteres.' using errcode='22023';
    end if;
    select m.client_id into client_key from public.memberships m
        where m.id=p_membership_id and m.gym_id=p_gym_id;
    if not found then
        raise exception 'El pago no existe en este gimnasio.' using errcode='P0002';
    end if;
    -- Mismo bloqueo usado al acumular planes nuevos. Después, bloqueo de la fila.
    perform pg_catalog.pg_advisory_xact_lock(client_key);
    select * into payment from public.memberships m
        where m.id=p_membership_id and m.gym_id=p_gym_id for update;
    if not found then
        raise exception 'El pago ya no está disponible. Actualiza la lista.' using errcode='P0002';
    end if;
    if payment.payment_status = 'void' then
        if p_action = 'void' then return to_jsonb(payment); end if;
        raise exception 'Este pago está anulado y no se puede corregir.' using errcode='22023';
    end if;
    if p_expected_revision is distinct from payment.payment_revision then
        raise exception 'Otra persona modificó este pago. Actualiza la lista antes de continuar.' using errcode='40001';
    end if;
    if p_action='correct' then
        if p_amount is null or p_amount < 0 or p_amount > 1000000000000 then
            raise exception 'El valor debe ser un número entero entre 0 y 1000000000000.' using errcode='22023';
        end if;
        if length(trim(coalesce(p_payment_method,''))) not between 1 and 60 or
           length(coalesce(p_payment_reference,'')) > 120 then
            raise exception 'Revisa el método de pago y la referencia (máximo 120 caracteres).' using errcode='22023';
        end if;
        if payment.amount is not distinct from p_amount and
           payment.amount_paid is not distinct from p_amount and
           coalesce(payment.payment_method,'') = trim(p_payment_method) and
           coalesce(payment.payment_reference,'') = trim(coalesce(p_payment_reference,'')) then
            raise exception 'No hay cambios en el valor, método o referencia.' using errcode='22023';
        end if;
    end if;
    update public.memberships m set
        amount = case when p_action='correct' then p_amount else m.amount end,
        amount_paid = case when p_action='correct' then p_amount else m.amount_paid end,
        payment_method = case when p_action='correct' then trim(p_payment_method) else m.payment_method end,
        payment_reference = case when p_action='correct' then trim(coalesce(p_payment_reference,'')) else m.payment_reference end,
        payment_status = case when p_action='void' then 'void' else 'posted' end,
        payment_revision = m.payment_revision + 1,
        payment_changed_at = clock_timestamp(),
        payment_changed_by = auth.uid(),
        payment_change_reason = trim(p_reason)
    where m.id=p_membership_id and m.gym_id=p_gym_id
    returning * into payment;
    return to_jsonb(payment);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ztattuz_change_store_sale(p_gym_id uuid, p_sale_id bigint, p_expected_revision bigint, p_action text, p_reason text, p_quantity integer DEFAULT NULL::integer, p_payment_method text DEFAULT NULL::text, p_payment_reference text DEFAULT NULL::text, p_customer_name text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    sale_row public.store_sales%rowtype;
    product_row public.store_products%rowtype;
    actor uuid := (select auth.uid());
    new_quantity integer;
    new_stock integer;
    new_method text;
begin
    if not private.user_has_gym_role(
        p_gym_id,
        array['admin']::text[]
    ) then
        raise exception 'Solo el administrador puede corregir ventas.'
            using errcode = '42501';
    end if;

    if p_action is null or p_action not in ('correct', 'void') then
        raise exception 'Acción de venta no válida.'
            using errcode = '22023';
    end if;

    if length(trim(coalesce(p_reason, ''))) not between 3 and 500 then
        raise exception 'Escribe un motivo de 3 a 500 caracteres.'
            using errcode = '22023';
    end if;

    select *
    into sale_row
    from public.store_sales s
    where s.id = p_sale_id
      and s.gym_id = p_gym_id
    for update;

    if not found then
        raise exception 'La venta no existe en este gimnasio.'
            using errcode = 'P0002';
    end if;

    if sale_row.sale_status = 'void' then
        raise exception 'Esta venta ya está anulada.'
            using errcode = '22023';
    end if;

    if p_expected_revision is distinct from sale_row.sale_revision then
        raise exception 'Otra persona modificó esta venta. Actualiza Finanzas.'
            using errcode = '40001';
    end if;

    perform pg_catalog.pg_advisory_xact_lock(sale_row.product_id);

    select *
    into product_row
    from public.store_products p
    where p.id = sale_row.product_id
      and p.gym_id = p_gym_id
    for update;

    if not found then
        raise exception 'El producto asociado ya no existe.'
            using errcode = 'P0002';
    end if;

    if p_action = 'void' then
        new_stock := product_row.stock_quantity + sale_row.quantity;

        update public.store_products
        set stock_quantity = new_stock,
            updated_by = actor,
            updated_at = clock_timestamp()
        where id = product_row.id
          and gym_id = p_gym_id;

        update public.store_sales
        set sale_status = 'void',
            sale_revision = sale_row.sale_revision + 1,
            sale_changed_at = clock_timestamp(),
            sale_changed_by = actor,
            sale_change_reason = trim(p_reason)
        where id = sale_row.id
          and gym_id = p_gym_id;
    else
        if coalesce(p_quantity, 0) <= 0 or p_quantity > 100000 then
            raise exception 'La cantidad debe estar entre 1 y 100000.'
                using errcode = '22023';
        end if;

        new_quantity := p_quantity;
        new_stock := product_row.stock_quantity
            + sale_row.quantity - new_quantity;

        if new_stock < 0 then
            raise exception 'No hay existencias suficientes para esa cantidad.'
                using errcode = '22023';
        end if;

        new_method := upper(trim(coalesce(
            nullif(p_payment_method, ''), sale_row.payment_method
        )));
        if new_method not in (
            'EFECTIVO', 'TRANSFERENCIA', 'TARJETA', 'OTRO'
        ) then
            raise exception 'El método de pago no es válido.'
                using errcode = '22023';
        end if;
        if length(coalesce(p_payment_reference, '')) > 120
           or length(coalesce(p_customer_name, '')) > 180
           or length(coalesce(p_notes, '')) > 1000 then
            raise exception 'Uno de los textos supera el límite permitido.'
                using errcode = '22023';
        end if;

        if new_quantity = sale_row.quantity
           and new_method = sale_row.payment_method
           and trim(coalesce(p_payment_reference, ''))
               = coalesce(sale_row.payment_reference, '')
           and trim(coalesce(p_customer_name, ''))
               = coalesce(sale_row.customer_name, '')
           and trim(coalesce(p_notes, '')) = coalesce(sale_row.notes, '') then
            raise exception 'No hay cambios en la venta.'
                using errcode = '22023';
        end if;

        update public.store_products
        set stock_quantity = new_stock,
            updated_by = actor,
            updated_at = clock_timestamp()
        where id = product_row.id
          and gym_id = p_gym_id;

        update public.store_sales
        set quantity = new_quantity,
            total_amount = unit_price * new_quantity,
            payment_method = new_method,
            payment_reference = trim(coalesce(p_payment_reference, '')),
            customer_name = trim(coalesce(p_customer_name, '')),
            notes = trim(coalesce(p_notes, '')),
            sale_status = 'posted',
            sale_revision = sale_row.sale_revision + 1,
            sale_changed_at = clock_timestamp(),
            sale_changed_by = actor,
            sale_change_reason = trim(p_reason)
        where id = sale_row.id
          and gym_id = p_gym_id;
    end if;

    select *
    into sale_row
    from public.store_sales s
    where s.id = p_sale_id
      and s.gym_id = p_gym_id;

    return to_jsonb(sale_row);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ztattuz_client_payments(p_gym_id uuid, p_client_id bigint, p_include_void boolean DEFAULT false, p_offset integer DEFAULT 0, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    result jsonb;
    page_size integer := least(greatest(coalesce(p_limit,50),1),100);
begin
    if not private.user_has_gym_role(p_gym_id, array['admin','receptionist']::text[]) then
        raise exception 'No tienes permiso para consultar estos pagos.' using errcode='42501';
    end if;
    if not private.client_belongs_to_gym(p_client_id,p_gym_id) then
        raise exception 'El cliente no existe en este gimnasio.' using errcode='P0002';
    end if;
    with selected as (
        select m.id, m.client_id, m.plan_id, coalesce(p.name,'Sin plan') as plan_name,
            m.start_date, m.end_date, coalesce(m.amount,m.amount_paid,0) as amount,
            m.payment_method, m.payment_reference, m.paid_at,
            m.payment_status, m.payment_revision, m.payment_changed_at,
            m.payment_change_reason
        from public.memberships m
        left join public.plans p on p.id=m.plan_id and p.gym_id=m.gym_id
        where m.gym_id=p_gym_id and m.client_id=p_client_id
          and (coalesce(p_include_void,false) or m.payment_status='posted')
        order by m.paid_at desc, m.id desc
        offset greatest(coalesce(p_offset,0),0) limit page_size+1
    ), page as (select * from selected limit page_size)
    select jsonb_build_object(
        'rows',coalesce((select jsonb_agg(to_jsonb(p) order by p.paid_at desc,p.id desc) from page p),'[]'::jsonb),
        'has_more',(select count(*) > page_size from selected)
    ) into result;
    return result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ztattuz_now()
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
    select now();
$function$
;

CREATE OR REPLACE FUNCTION public.ztattuz_payment_history(p_gym_id uuid, p_membership_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
    if not private.user_has_gym_role(p_gym_id,array['admin','receptionist']::text[]) then
        raise exception 'No tienes permiso para consultar este historial.' using errcode='42501';
    end if;
    if not exists(select 1 from public.memberships where id=p_membership_id and gym_id=p_gym_id) then
        raise exception 'El pago no existe en este gimnasio.' using errcode='P0002';
    end if;
    select coalesce(jsonb_agg(to_jsonb(a) order by a.created_at desc,a.id desc),'[]'::jsonb) into result
    from (
        select id,created_at,actor_email,actor_role,action,summary,details
        from public.audit_logs
        where gym_id=p_gym_id and entity_type='memberships' and entity_id=p_membership_id::text
        order by created_at desc,id desc limit 200
    ) a;
    return result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ztattuz_today()
 RETURNS date
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
    select (
        now() at time zone 'America/Bogota'
    )::date;
$function$
;

